// Formatting helpers
function formatUSD(num) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2 }).format(num);
}

function formatUSDWhole(num) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(num);
}

// Determine Initial City from URL or LocalStorage
function getInitialCity() {
  try {
    const params = new URLSearchParams(window.location.search);
    const urlCity = (params.get('city') || '').toLowerCase();
    if (CITY_REGISTRY[urlCity]) {
      return urlCity;
    }
    const saved = localStorage.getItem('watchdog_city');
    if (saved && CITY_REGISTRY[saved]) {
      return saved;
    }
  } catch (e) {
    // ignore storage errors
  }
  return 'clifton';
}

// Data Refresh & Verification Audit Log Loader
let auditLogData = null;

async function loadAuditLog() {
  try {
    const res = await fetch('data/audit_log.json');
    if (res.ok) {
      auditLogData = await res.json();
      updateRefreshBadges(auditLogData);
    } else {
      updateRefreshBadges(null);
    }
  } catch (err) {
    updateRefreshBadges(null);
  }
}

function updateRefreshBadges(log) {
  let displayDate = 'October 31, 2026';
  let shortDate = 'Oct 31, 2026';
  let statusText = '100% Verified (0.00% Hallucination Rate)';

  if (log && log.lastRun) {
    try {
      const cleanIso = log.lastRun.replace(' UTC', 'Z').replace(' ', 'T');
      const parsed = new Date(cleanIso);
      if (!isNaN(parsed.getTime())) {
        displayDate = parsed.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
        shortDate = parsed.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      } else if (log.date) {
        displayDate = log.date;
        shortDate = log.date;
      }
    } catch (e) {
      if (log.date) {
        displayDate = log.date;
        shortDate = log.date;
      }
    }
  }

  const headerBadge = document.getElementById('header-refresh-badge');
  if (headerBadge) {
    headerBadge.textContent = `🕒 Last Refreshed: ${shortDate}`;
    headerBadge.setAttribute('title', `Automated Weekly Refresh: ${displayDate} • Status: ${statusText}`);
  }

  const footerLastRefreshed = document.getElementById('footer-last-refreshed');
  if (footerLastRefreshed) {
    footerLastRefreshed.innerHTML = `🔄 <strong>Last Refreshed:</strong> ${displayDate} &bull; <span style="color: #10b981;">● ${statusText}</span>`;
  }

  const footerSchedule = document.getElementById('footer-refresh-schedule');
  if (footerSchedule) {
    footerSchedule.textContent = '⏱️ Automated Refresh: Weekly Every Monday at 06:00 UTC (GitHub Actions)';
  }

  document.querySelectorAll('.last-refreshed-date').forEach(el => {
    el.textContent = displayDate;
  });
}

// Highlight Active Hub Link in Navigation Bar
function syncNavActive() {
  const currentPath = window.location.pathname.split('/').pop() || 'index.html';
  document.querySelectorAll('.nav-menu a.nav-item-btn').forEach(link => {
    const href = link.getAttribute('href');
    const isCurrent = href === currentPath || (currentPath === '' && href === 'index.html');
    link.classList.toggle('active', isCurrent);
    if (isCurrent) {
      link.setAttribute('aria-current', 'page');
    } else {
      link.removeAttribute('aria-current');
    }
  });
}

// Initialize Application
async function initApp() {
  currentCity = getInitialCity();
  syncNavActive();
  setupTabs();
  setupCollapsibleSections();
  setupCitySwitcher();
  loadAuditLog();

  // Ensure the current page has an active tab pane
  if (!document.querySelector('.tab-pane.active')) {
    const firstPane = document.querySelector('.tab-pane');
    if (firstPane) {
      firstPane.classList.add('active');
      const firstTabBtn = document.querySelector(`.hub-subnav-btn[data-tab="${firstPane.id}"]`) || document.querySelector(`.tab-btn[data-tab="${firstPane.id}"]`);
      if (firstTabBtn) firstTabBtn.classList.add('active');
    }
  }

  await switchCity(currentCity, false);

  // Initialize section share buttons, omnibox fast teleport, nav tools menu, and process deep links
  initSectionShareButtons();
  setupOmnibox();
  setupNavToolsMenu();
  handleUrlHash();

  // Check for URL parameters to preload calculator or deep-link to properties, appeals, or relief calculator
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.has('embed') && document.body) {
    document.body.classList.add('embed-mode');
  }
  if (urlParams.has('calc')) {
    const val = parseInt(urlParams.get('calc'), 10);
    const input = document.getElementById('calc-assessment-input');
    const slider = document.getElementById('calc-assessment-slider');
    if (!isNaN(val) && input) {
      input.value = val;
      if (slider) slider.value = val;
      input.dispatchEvent(new Event('input'));
    }
  }

  if (urlParams.has('pin') || urlParams.has('id')) {
    const targetPin = urlParams.get('pin') || urlParams.get('id');
    setTimeout(() => {
      handlePinDeepLink(targetPin, urlParams.has('appeal'), urlParams.has('receipt'), urlParams.has('mod4') || urlParams.has('verify'));
    }, 250);
  } else if (urlParams.has('street') || urlParams.has('search')) {
    const streetQuery = urlParams.get('street') || urlParams.get('search');
    const searchInput = document.getElementById('prop-search-input');
    if (searchInput) {
      searchInput.value = streetQuery;
      if (typeof applyPropertyFilters === 'function') {
        applyPropertyFilters();
      }
    }
  } else if (urlParams.has('rebate') || urlParams.has('relief')) {
    setTimeout(() => {
      openReliefCalculator();
    }, 250);
  } else if (urlParams.has('overassessed') || urlParams.has('savings') || urlParams.has('appeals') || urlParams.has('appeal-roll')) {
    setTimeout(() => {
      if (typeof toggleOverAssessedFilter === 'function' && !appealFilterActive) {
        toggleOverAssessedFilter();
      }
    }, 250);
  }

  // Load live election results & start 3-minute recurring refresh
  loadElectionResults(currentCity).then(() => {
    if (document.getElementById('election-results-container')) {
      renderElectionResults();
    } else {
      updateElectionRibbonsAndPreviews();
    }
    startElectionAutoRefresh();
  });
}

