function updateHeaderTownOptions(county, selectedTownId) {
  const townSelect = document.getElementById('cascade-town-select');
  if (!townSelect) return;

  let towns = NORTH_JERSEY_TOWNS;
  if (county && county !== 'all') {
    towns = NORTH_JERSEY_TOWNS.filter(t => t.county.toLowerCase().includes(county.toLowerCase().replace(' county', '')));
  }

  if (county === 'all') {
    const counties = ['Passaic County', 'Bergen County', 'Essex County', 'Morris County'];
    let html = '';
    for (const c of counties) {
      const cTowns = towns.filter(t => t.county === c);
      html += `<optgroup label="${c} (${cTowns.length})">`;
      for (const t of cTowns) {
        const isSel = t.id === selectedTownId ? 'selected' : '';
        html += `<option value="${t.id}" data-county="${t.county}" ${isSel}>${t.icon} ${t.name} (${t.rate}) ${t.isHub ? '⭐' : ''}</option>`;
      }
      html += `</optgroup>`;
    }
    townSelect.innerHTML = html;
  } else {
    let html = '';
    for (const t of towns) {
      const isSel = t.id === selectedTownId ? 'selected' : '';
      html += `<option value="${t.id}" data-county="${t.county}" ${isSel}>${t.icon} ${t.name} (${t.rate}) ${t.isHub ? '⭐' : ''}</option>`;
    }
    townSelect.innerHTML = html;
  }

  if (selectedTownId) {
    townSelect.value = selectedTownId;
  }
}

// ==========================================================================
// OPTION A: INTERACTIVE LOCATION PICKER MODAL (ALL 47 TOWNS)
// ==========================================================================
let activeLocationPickerCounty = 'Passaic County';
let activeLocationPickerSearch = '';
let locationPickerEventsInitialized = false;

function openLocationPickerModal() {
  const modal = document.getElementById('location-picker-dialog');
  if (!modal) return;
  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;
  activeLocationPickerCounty = meta.county || 'Passaic County';
  activeLocationPickerSearch = '';

  const searchInput = document.getElementById('loc-search-input');
  if (searchInput) searchInput.value = '';
  const clearBtn = document.getElementById('btn-loc-clear');
  if (clearBtn) clearBtn.style.display = 'none';

  // Sync active county tab
  document.querySelectorAll('.loc-county-tab').forEach(tab => {
    const isMatch = tab.dataset.locCounty === activeLocationPickerCounty;
    tab.classList.toggle('active', isMatch);
    tab.setAttribute('aria-selected', isMatch ? 'true' : 'false');
  });

  renderLocationPickerGrid(activeLocationPickerCounty, '');

  if (typeof modal.showModal === 'function') {
    modal.showModal();
  } else {
    modal.setAttribute('open', '');
  }

  if (searchInput) {
    setTimeout(() => searchInput.focus(), 50);
  }
}

function closeLocationPickerModal() {
  const modal = document.getElementById('location-picker-dialog');
  if (!modal) return;
  if (typeof modal.close === 'function') {
    modal.close();
  } else {
    modal.removeAttribute('open');
  }
}

function clearLocationSearch() {
  const searchInput = document.getElementById('loc-search-input');
  if (searchInput) {
    searchInput.value = '';
    searchInput.focus();
  }
  const clearBtn = document.getElementById('btn-loc-clear');
  if (clearBtn) clearBtn.style.display = 'none';
  activeLocationPickerSearch = '';
  renderLocationPickerGrid(activeLocationPickerCounty, '');
}

function renderLocationPickerGrid(countyFilter = null, searchTerm = '') {
  const grid = document.getElementById('loc-towns-grid');
  if (!grid) return;

  const county = countyFilter || activeLocationPickerCounty || 'all';
  const term = (searchTerm || '').trim().toLowerCase();

  let towns = NORTH_JERSEY_TOWNS;
  if (county && county !== 'all') {
    towns = towns.filter(t => t.county.toLowerCase().includes(county.toLowerCase().replace(' county', '')));
  }

  if (term) {
    towns = NORTH_JERSEY_TOWNS.filter(t => 
      t.name.toLowerCase().includes(term) || 
      t.county.toLowerCase().includes(term)
    );
  }

  if (towns.length === 0) {
    grid.innerHTML = `
      <div style="grid-column: 1 / -1; padding: 24px; text-align: center; color: var(--text-muted);">
        <p style="font-size: 1.1rem; margin-bottom: 4px;">🔍 No municipalities found for "${term}"</p>
        <p style="font-size: 0.82rem;">Try searching for Clifton, Wayne, Montclair, Paramus, or Morristown.</p>
      </div>
    `;
    return;
  }

  grid.innerHTML = towns.map(t => {
    const isCurrent = t.id === currentCity;
    return `
      <button type="button" class="loc-town-card ${isCurrent ? 'active' : ''}" onclick="selectLocationTown('${t.id}', '${t.county}')" aria-label="Select ${t.name}">
        <div class="loc-card-header">
          <span class="loc-card-icon" aria-hidden="true">${t.icon || '🏘️'}</span>
          <span class="loc-card-name">${t.name}</span>
          ${t.isHub ? '<span class="loc-card-hub-badge">⭐ Full Hub</span>' : ''}
          ${isCurrent ? '<span class="loc-card-active-badge">Active</span>' : ''}
        </div>
        <div class="loc-card-body">
          <span class="loc-card-county">${t.county}</span>
          <span class="loc-card-rate">Effective Rate: <strong>${t.rate}</strong></span>
        </div>
      </button>
    `;
  }).join('');
}

async function selectLocationTown(townId, county) {
  closeLocationPickerModal();
  if (CITY_REGISTRY[townId]) {
    if (townId !== currentCity) {
      await switchCity(townId, true);
    }
    const currentTab = typeof currentActiveTab !== 'undefined' ? currentActiveTab : '';
    if (currentTab === 'tab-surrounding' || (typeof window !== 'undefined' && window.location.hash.includes('tab-surrounding'))) {
      if (typeof selectSpecificTownComparison === 'function') {
        selectSpecificTownComparison(townId, county);
      }
    }
  } else {
    navigateToTownComparison(townId, county);
  }
}

function setupLocationPickerEvents() {
  if (locationPickerEventsInitialized) return;
  locationPickerEventsInitialized = true;

  const searchInput = document.getElementById('loc-search-input');
  const clearBtn = document.getElementById('btn-loc-clear');

  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      const val = e.target.value || '';
      activeLocationPickerSearch = val;
      if (clearBtn) clearBtn.style.display = val ? 'inline-block' : 'none';
      renderLocationPickerGrid(activeLocationPickerCounty, val);
    });

    searchInput.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeLocationPickerModal();
      } else if (e.key === 'Enter') {
        const firstCard = document.querySelector('#loc-towns-grid .loc-town-card');
        if (firstCard) firstCard.click();
      }
    });
  }

  document.querySelectorAll('.loc-county-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      const county = tab.dataset.locCounty;
      activeLocationPickerCounty = county;
      document.querySelectorAll('.loc-county-tab').forEach(t => {
        const isMatch = t === tab;
        t.classList.toggle('active', isMatch);
        t.setAttribute('aria-selected', isMatch ? 'true' : 'false');
      });
      if (searchInput) {
        searchInput.value = '';
        if (clearBtn) clearBtn.style.display = 'none';
      }
      activeLocationPickerSearch = '';
      renderLocationPickerGrid(county, '');
    });
  });

  const modal = document.getElementById('location-picker-dialog');
  if (modal && (typeof HTMLDialogElement === 'undefined' || !('closedBy' in HTMLDialogElement.prototype))) {
    modal.addEventListener('click', (e) => {
      // Light-dismiss fallback: only trigger when clicking the backdrop itself
      if (e.target !== modal) return;
      const rect = modal.getBoundingClientRect();
      const isInDialog = (
        rect.top <= e.clientY && e.clientY <= rect.top + rect.height &&
        rect.left <= e.clientX && e.clientX <= rect.left + rect.width
      );
      if (!isInDialog) {
        closeLocationPickerModal();
      }
    });
  }
}

// Setup Smart Location Pill & Switchers in Header
function setupCitySwitcher() {
  setupLocationPickerEvents();

  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;

  // Sync Option A Location Pill labels
  const pillTown = document.getElementById('header-active-town-name');
  if (pillTown) {
    pillTown.textContent = meta.name;
  }
  const pillCounty = document.getElementById('header-active-county-name');
  if (pillCounty) {
    pillCounty.textContent = `(${meta.countyShort.replace(' County', '')} Co.)`;
  }

  // Backward compatible cascading selects if present
  const countySelect = document.getElementById('cascade-county-select');
  const townSelect = document.getElementById('cascade-town-select');

  if (countySelect) {
    countySelect.value = meta.county;
    countySelect.addEventListener('change', (e) => {
      const county = e.target.value;
      updateHeaderTownOptions(county, currentCity);
    });
  }

  updateHeaderTownOptions(meta.county, currentCity);

  if (townSelect) {
    townSelect.addEventListener('change', (e) => {
      const townId = e.target.value;
      if (!townId) return;
      const opt = townSelect.options[townSelect.selectedIndex];
      const county = opt ? opt.getAttribute('data-county') : '';

      if (CITY_REGISTRY[townId]) {
        if (townId !== currentCity) {
          switchCity(townId, true);
        }
      } else {
        navigateToTownComparison(townId, county);
      }
    });
  }
}

function navigateToTownComparison(townId, county) {
  const currentFile = window.location.pathname.split('/').pop() || 'index.html';
  if (currentFile === 'budgets.html') {
    if (typeof switchTab === 'function') {
      switchTab('tab-surrounding');
    }
    selectSpecificTownComparison(townId, county);
  } else {
    window.location.href = `budgets.html?town=${encodeURIComponent(townId)}&county=${encodeURIComponent(county || '')}#tab-surrounding`;
  }
}

// Switch Active Municipality across all 6 switchable cities
async function switchCity(cityId, updateUrl = true) {
  currentCity = CITY_REGISTRY[cityId] ? cityId : 'clifton';
  if (typeof window !== 'undefined') window.currentCity = currentCity;
  const meta = CITY_REGISTRY[currentCity];

  try {
    localStorage.setItem('watchdog_city', currentCity);
    if (updateUrl && window.history && window.history.replaceState) {
      const url = new URL(window.location.href);
      if (currentCity !== 'clifton') {
        url.searchParams.set('city', currentCity);
      } else {
        url.searchParams.delete('city');
      }
      window.history.replaceState({}, '', url.toString());
    }
  } catch (e) {
    // ignore URL/storage restrictions
  }

  // Update Option A Location Pill labels
  const pillTown = document.getElementById('header-active-town-name');
  if (pillTown) {
    pillTown.textContent = meta.name;
  }
  const pillCounty = document.getElementById('header-active-county-name');
  if (pillCounty) {
    pillCounty.textContent = `(${meta.countyShort.replace(' County', '')} Co.)`;
  }

  // Update cascading header selectors & active badge if present
  const countySelect = document.getElementById('cascade-county-select');
  if (countySelect) {
    countySelect.value = meta.county;
  }
  updateHeaderTownOptions(meta.county, currentCity);

  const activeBadgeName = document.getElementById('cascade-active-town-name');
  if (activeBadgeName) {
    activeBadgeName.textContent = `${meta.name} (${meta.countyShort.replace(' County', '')})`;
  }

  // Update legacy buttons if present
  document.querySelectorAll('.city-switch-btn').forEach(btn => {
    const isMatch = btn.getAttribute('data-city') === currentCity;
    btn.classList.toggle('active', isMatch);
    btn.setAttribute('aria-pressed', isMatch ? 'true' : 'false');
  });

  await loadAllData(currentCity);
  applyCityStaticCopy(currentCity);

  // Reset pagination to page 1 when switching cities
  propCurrentPage = 1;

  // Render sections conditionally based on DOM elements present on the active page
  if (document.getElementById('calc-assessment-input')) setupCalculator();
  if (document.getElementById('boe-line-items') || document.getElementById('tab-budgets')) renderBudgets();
  if (document.getElementById('boe-spending-efficiency-container')) renderEducationSpendingAudit();
  if (document.getElementById('passaic-county-services-container')) renderPassaicCountyServices();
  if (document.getElementById('demo-citywide-banner') || document.getElementById('tab-demographics') || document.getElementById('demo-population')) renderDemographics();
  if (document.getElementById('properties-table-body') || document.getElementById('properties-cards-grid') || document.getElementById('tab-properties')) {
    renderProperties();
    setupPropertyFilters();
  }
  if (document.getElementById('surrounding-table-body') || document.getElementById('surrounding-cards-container') || document.getElementById('tab-surrounding')) renderSurroundingTowns();
  if (document.getElementById('benefits-plans-container') || document.getElementById('tab-benefits')) renderBenefits();
  if (document.getElementById('controversies-cards-container') || document.getElementById('tab-controversies')) renderControversies();
  if (document.getElementById('staff-table-body')) {
    renderStaffTable('all', document.getElementById('staff-search-input')?.value || '');
    setupStaffFilters();
  }
  if (document.getElementById('ethics-cards-container') || document.getElementById('ethics-cards-grid') || document.getElementById('tab-ethics')) {
    renderEthicsCards('all');
    setupEthicsFilters();
  }
  if (document.getElementById('vendors-cards-container') || document.getElementById('vendors-cards-grid') || document.getElementById('tab-vendors')) {
    renderVendorsCards();
  }
  if (document.getElementById('intel-report-receipt') || document.getElementById('tab-intelligence')) {
    setupInvestigationTools();
    renderIntelligenceReports();
  }
  if (document.getElementById('pilot-comparison-container') || document.getElementById('tab-commercial-pilot')) renderCommercialPilot();
  if (document.getElementById('city-docs-tbody') || document.getElementById('tab-city-docs')) renderCityDocumentsArchive();
  if (document.getElementById('tax-flow-diagram') || document.getElementById('tab-fair-tax')) renderFairTaxEngine();
  if (document.getElementById('election-candidates-grid') || document.getElementById('election-ballot-overview-grid') || document.getElementById('tab-election')) {
    renderElectionHub();
    setupElectionControls();
  } else {
    loadElectionResults(currentCity, true).then(() => updateElectionRibbonsAndPreviews());
  }
}


