// Helper: Extract Street Name from Address (e.g. "352 Grove St" -> "Grove St")
function extractStreetName(addr) {
  if (!addr) return '';
  return addr.replace(/^[0-9]+[A-Za-z0-9\-\/]*\s+/, '').trim();
}

// --------------------------------------------------------------------------
// FEATURE 3: Street & Block Report Card
// --------------------------------------------------------------------------
function updateStreetReportCard(filteredList, rawQuery) {
  const container = document.getElementById('street-report-card-container');
  if (!container) return;
  if (!filteredList || filteredList.length < 3 || !propertyAssessmentsData?.properties) {
    container.style.display = 'none';
    return;
  }

  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;
  const townAvgAssessed = propertyAssessmentsData.summaryStats?.averageAssessed || meta.sliderDefault || 180523;

  // Check if filtered list represents a street or block
  let detectedStreet = '';
  let detectedBlock = '';

  const q = (rawQuery || '').trim().toLowerCase();
  if (q.startsWith('block ') || q.startsWith('b:')) {
    detectedBlock = q.replace(/^block\s+/i, '').replace(/^b:\s*/i, '').trim();
  }

  // Count streets in the filtered subset
  const streetCounts = {};
  for (let i = 0; i < filteredList.length; i++) {
    const st = extractStreetName(filteredList[i].address);
    if (st) streetCounts[st] = (streetCounts[st] || 0) + 1;
  }

  const sortedStreets = Object.entries(streetCounts).sort((a, b) => b[1] - a[1]);
  if (sortedStreets.length > 0 && (sortedStreets[0][1] >= 3) && (sortedStreets[0][1] / filteredList.length >= 0.35 || q.length > 2)) {
    detectedStreet = sortedStreets[0][0];
  }

  if (!detectedStreet && !detectedBlock) {
    container.style.display = 'none';
    return;
  }

  // Calculate statistics for this street/block subset
  const streetProps = detectedStreet
    ? filteredList.filter(p => extractStreetName(p.address).toLowerCase() === detectedStreet.toLowerCase())
    : filteredList;

  if (streetProps.length < 3) {
    container.style.display = 'none';
    return;
  }

  let totalAssessed = 0;
  let totalLand = 0;
  let totalBldg = 0;
  let totalTax = 0;
  let totalSchool = 0;
  let minTax = Infinity;
  let maxTax = -Infinity;

  for (let i = 0; i < streetProps.length; i++) {
    const p = streetProps[i];
    const a = p.assessedTotal || 0;
    const t = p.annualTax || 0;
    totalAssessed += a;
    totalLand += (p.assessedLand || 0);
    totalBldg += (p.assessedBuilding || 0);
    totalTax += t;
    totalSchool += (p.schoolTax || (t * 0.5));
    if (t < minTax) minTax = t;
    if (t > maxTax) maxTax = t;
  }

  const count = streetProps.length;
  const avgAssessed = Math.round(totalAssessed / count);
  const avgTax = totalTax / count;
  const diffPct = ((avgAssessed - townAvgAssessed) / townAvgAssessed) * 100;
  const diffSign = diffPct >= 0 ? '+' : '';
  const diffClass = diffPct > 0 ? 'higher' : 'lower';
  const landSharePct = totalAssessed > 0 ? Math.round((totalLand / totalAssessed) * 100) : 35;
  const bldgSharePct = 100 - landSharePct;

  const targetName = detectedStreet ? `${detectedStreet}` : `Block ${detectedBlock}`;

  container.innerHTML = `
    <div class="street-report-banner">
      <div class="street-report-header">
        <div class="street-report-title">
          <h3><span>📍</span> ${escapeHtml(targetName)} Report Card (${escapeHtml(meta.name)}, ${escapeHtml(meta.countyShort)})</h3>
          <div class="street-report-meta">Aggregated real-time metrics across ${count.toLocaleString()} official MOD-IV residential parcels</div>
        </div>
        <span class="pill-tag" style="background: #2563eb; color: #fff; font-weight: 700;">${count} Homes on Roll</span>
      </div>

      <div class="street-metrics-grid">
        <div class="street-metric-item">
          <span class="street-metric-lbl">Street Avg Assessment</span>
          <span class="street-metric-val">${formatUSDWhole(avgAssessed)}</span>
          <span class="street-metric-sub ${diffClass}">${diffSign}${diffPct.toFixed(1)}% vs. town avg (${formatUSDWhole(townAvgAssessed)})</span>
        </div>
        <div class="street-metric-item">
          <span class="street-metric-lbl">Street Avg Annual Tax</span>
          <span class="street-metric-val">${formatUSD(avgTax)}</span>
          <span class="street-metric-sub">Range: ${formatUSDWhole(minTax)} – ${formatUSDWhole(maxTax)}</span>
        </div>
        <div class="street-metric-item">
          <span class="street-metric-lbl">Total Tax Contributed</span>
          <span class="street-metric-val">${formatUSDWhole(totalTax)}</span>
          <span class="street-metric-sub">Annual property tax levy from this street</span>
        </div>
        <div class="street-metric-item">
          <span class="street-metric-lbl">${escapeHtml(meta.schoolDistrictShort)} Share</span>
          <span class="street-metric-val" style="color: var(--color-school);">${formatUSDWhole(totalSchool)}</span>
          <span class="street-metric-sub">Funds local classrooms &amp; teachers</span>
        </div>
        <div class="street-metric-item">
          <span class="street-metric-lbl">Land vs. Building Split</span>
          <span class="street-metric-val" style="font-size: 1.05rem;">${landSharePct}% / ${bldgSharePct}%</span>
          <span class="street-metric-sub">Land: ${formatUSDWhole(Math.round(totalLand/count))} • Bldg: ${formatUSDWhole(Math.round(totalBldg/count))}</span>
        </div>
      </div>

      <div class="street-actions-row">
        <button type="button" class="btn-street-action" onclick="openAppealAnalyzer('${streetProps[0].id}')">
          <span>⚖️</span> Check Appeal Comps for Homes on ${escapeHtml(targetName)}
        </button>
        <button type="button" class="btn-street-action" onclick="openReliefCalculator(${avgTax}, ${avgAssessed}, '${escapeHtml(targetName)} (Average)')">
          <span>🧓</span> Calculate State Rebates for ${escapeHtml(targetName)} Avg
        </button>
        <button type="button" class="btn-street-action" onclick="resetStreetSearch()">
          <span>✕</span> Show All ${escapeHtml(meta.name)} Homes
        </button>
      </div>
    </div>
  `;
  container.style.display = 'block';
}

function viewStreetReport(addr) {
  const st = extractStreetName(addr);
  const searchInput = document.getElementById('prop-search-input');
  if (searchInput && st) {
    searchInput.value = st;
    if (typeof applyPropertyFilters === 'function') {
      applyPropertyFilters();
    }
    const container = document.getElementById('street-report-card-container');
    if (container) {
      container.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }
}

function resetStreetSearch() {
  const searchInput = document.getElementById('prop-search-input');
  if (searchInput) {
    searchInput.value = '';
    if (typeof applyPropertyFilters === 'function') {
      applyPropertyFilters();
    }
  }
}

// --------------------------------------------------------------------------
// FEATURE 1: ⚖️ Tax Appeal Analyzer & Comparable Finder
// --------------------------------------------------------------------------
function renderAppealEvidenceText() {
  if (!activeAppealProperty) return '';
  const target = activeAppealProperty;
  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;
  const eqRatio = meta.equalizationRatio || 33.3;
  const rate = meta.rateNum || 6.527;
  const topComps = activeAppealComps || [];
  const compMedianAssess = activeAppealMedian || target.assessedTotal;
  const assessDiff = activeAppealDiff || 0;
  const assessDiffPct = activeAppealDiffPct || 0;
  const specs = activeAppealSpecs;

  const corridorLower = +(eqRatio * 0.85).toFixed(1);
  const corridorUpper = +(eqRatio * 1.15).toFixed(1);
  const hasRecentSale = target.salePrice > 50000;
  const saleRatio = hasRecentSale ? (target.assessedTotal / target.salePrice) * 100 : 0;
  const isCh123OverAssessed = hasRecentSale && saleRatio > corridorUpper;

  // Format Condition & Legal Grounds
  let conditionText = 'Standard / Maintained (Street Typical)';
  let groundsText = '';
  if (specs.condition === 'dated') {
    conditionText = 'Unrenovated / Original (Dated Kitchen & Bathrooms, Deferred Interior Updating)';
    groundsText = `Subject building improvement assessment ($${(target.assessedBuilding || 0).toLocaleString()}) reflects updated/modern improvements under Class 2, but subject dwelling features ${specs.bedrooms} bedrooms and ${specs.bathrooms} baths in largely original/unrenovated interior condition. A negative physical obsolescence adjustment is warranted under N.J.A.C. 18:12 to align with modernized street comparables.`;
  } else if (specs.condition === 'deferred') {
    conditionText = 'Substantial Deferred Maintenance / Structural Repairs Required';
    groundsText = `Subject dwelling requires substantial structural / mechanical repairs and major deferred maintenance. The current building assessment does not account for necessary capital depreciation under N.J.S.A. 54:3-21, creating an inequitable assessment relative to neighboring properties.`;
  } else if (specs.condition === 'renovated') {
    conditionText = 'Recently Modernized / Renovated';
    groundsText = `Subject assessment of $${target.assessedTotal.toLocaleString()} exceeds the statutory common level corridor (Chapter 123) when measured against certified arms-length street deed sales and comparable neighborhood parcels.`;
  } else {
    conditionText = 'Standard / Maintained (Comparable to Street Norm)';
    groundsText = `Subject dwelling features ${specs.bedrooms} bedrooms and ${specs.bathrooms} baths. The subject's total assessment of $${target.assessedTotal.toLocaleString()} exceeds the prevailing street median of $${compMedianAssess.toLocaleString()} (${assessDiffPct > 0 ? '+' : ''}${assessDiffPct.toFixed(1)}%), warranting an equalization reduction under N.J.A.C. 18:12.`;
  }

  const sqftVal = parseInt(specs.sqft, 10);
  const sqftLine = (sqftVal && sqftVal > 100)
    ? `• Petitioner Estimated Living Area: ${sqftVal.toLocaleString()} sq ft ($${(((target.assessedBuilding || target.assessedTotal)) / sqftVal).toFixed(2)} bldg assess / sq ft)\n`
    : '';

  const ch123Text = isCh123OverAssessed
    ? `• CHAPTER 123 STATUTORY REMEDY: Subject assessment-to-sale ratio is ${saleRatio.toFixed(1)}%, exceeding the ${corridorUpper}% statutory ceiling. Mandated relief under N.J.S.A. 54:51A-6 requires reduction to common level ratio (${eqRatio.toFixed(1)}%).\n`
    : '';

  const reliefSought = assessDiff > 0
    ? `Reduce net assessment to prevailing street baseline of $${compMedianAssess.toLocaleString()} (Estimated Tax Reduction: $${((assessDiff / 100) * rate).toFixed(2)} / year)`
    : `Net assessment aligns with or falls below street median ($${compMedianAssess.toLocaleString()}). Relief sought under N.J.A.C. 18:12 based on physical condition / obsolescence: adjust building assessment ($${(target.assessedBuilding || 0).toLocaleString()}) reflecting documented interior condition defects.`;

  return `================================================================================
PETITION OF APPEAL EVIDENCE TABLE (NJ FORM A-1)
County Board of Taxation Assessment Appeal
================================================================================
MUNICIPALITY: ${meta.name.toUpperCase()} (DISTRICT ${meta.districtCode}) | TAX YEAR: 2026
SUBJECT PROPERTY: ${target.address.toUpperCase()} | BLOCK ${target.block}, LOT ${target.lot}${target.qual ? ', QUAL ' + target.qual : ''}
TOTAL NET ASSESSMENT: $${target.assessedTotal.toLocaleString()} (LAND: $${(target.assessedLand || 0).toLocaleString()} | BLDG: $${(target.assessedBuilding || 0).toLocaleString()})
ANNUAL PROPERTY TAX: $${target.annualTax.toFixed(2)} | CERTIFIED TAX RATE: ${rate.toFixed(3)}%
MUNICIPAL EQUALIZATION RATIO: ${eqRatio.toFixed(1)}% | COMMON LEVEL RANGE: ${corridorLower}% TO ${corridorUpper}%

PETITIONER'S PROPERTY SPECIFICATIONS & INTERIOR DISCLOSURE:
• Assessor Exterior Code (MOD-IV): ${target.bldgDesc || 'Class 2'} | Built: ${target.yearBuilt > 0 ? target.yearBuilt : 'N/A'} | Lot: ${target.lotSize || (target.acres ? target.acres + ' AC' : 'Standard')}
• Verified Room Count: ${specs.bedrooms} Bedrooms | ${specs.bathrooms} Bathrooms
${sqftLine}${ch123Text}• Interior Condition & Obsolescence: ${conditionText}

GROUNDS FOR APPEAL (N.J.S.A. 54:3-21 & N.J.A.C. 18:12-1.1):
${groundsText}

OFFICIAL MOD-IV COMPARABLE ASSESSMENTS ON SAME STREET / SECTION:
${topComps.map((c, i) => `Comp #${i+1}: ${c.address.toUpperCase()} | Block ${c.block}, Lot ${c.lot} | Assessed: $${c.assessedTotal.toLocaleString()} | Tax: $${c.annualTax.toFixed(2)} | Built: ${c.yearBuilt || 'N/A'}${c.salePrice > 100 ? ` | Deed Sale: $${c.salePrice.toLocaleString()} (${c.deedDate || 'N/A'})` : ''}`).join('\n')}

BENCHMARK STREET MEDIAN ASSESSMENT: $${compMedianAssess.toLocaleString()}
ESTIMATED ASSESSMENT VARIANCE: ${assessDiff >= 0 ? '+' : ''}$${assessDiff.toLocaleString()} (${assessDiffPct.toFixed(1)}%)
INDICATED RELIEF SOUGHT: ${reliefSought}
================================================================================`;
}

function updateAppealInteriorSpecs() {
  const bedsEl = document.getElementById('appeal-spec-beds');
  const bathsEl = document.getElementById('appeal-spec-baths');
  const sqftEl = document.getElementById('appeal-spec-sqft');
  const condEl = document.getElementById('appeal-spec-condition');

  if (bedsEl) activeAppealSpecs.bedrooms = bedsEl.value;
  if (bathsEl) activeAppealSpecs.bathrooms = bathsEl.value;
  if (sqftEl) activeAppealSpecs.sqft = sqftEl.value.trim();
  if (condEl) activeAppealSpecs.condition = condEl.value;

  // Update Form A-1 text box
  const textEl = document.getElementById('form-a1-text-block');
  if (textEl) {
    textEl.textContent = renderAppealEvidenceText();
  }

  // Update dynamic metric pills
  if (activeAppealProperty) {
    const bldgVal = activeAppealProperty.assessedBuilding || activeAppealProperty.assessedTotal;
    const numBeds = parseInt(activeAppealSpecs.bedrooms, 10) || 1;
    const bedPill = document.getElementById('appeal-metric-per-bed');
    if (bedPill) {
      bedPill.textContent = `Bldg Assess / Bed: $${Math.round(bldgVal / numBeds).toLocaleString()}`;
    }

    const sqftPill = document.getElementById('appeal-metric-per-sqft');
    if (sqftPill) {
      const sqftVal = parseInt(activeAppealSpecs.sqft, 10);
      if (sqftVal && sqftVal > 100) {
        sqftPill.textContent = `Bldg / Sq Ft: $${(bldgVal / sqftVal).toFixed(2)}`;
        sqftPill.style.display = 'inline-flex';
      } else {
        sqftPill.style.display = 'none';
      }
    }
  }
}

async function openAppealAnalyzer(propId) {
  if (!propertyAssessmentsData || !propertyAssessmentsData.properties) {
    if (typeof loadAllData === 'function') {
      try {
        await loadAllData(currentCity);
      } catch (e) {}
    }
  }
  const dialog = document.getElementById('appeal-analyzer-dialog');
  if (!dialog) {
    window.location.href = propId ? `properties.html#property-${propId}` : 'properties.html';
    return;
  }
  if (!propertyAssessmentsData || !propertyAssessmentsData.properties) return;
  const props = propertyAssessmentsData.properties;
  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;

  let target = null;
  if (propId) {
    target = props.find(p => p.id === propId);
  }
  if (!target) {
    target = (currentFilteredProperties && currentFilteredProperties.length > 0)
      ? currentFilteredProperties[0]
      : props[0];
  }
  if (!target) return;

  activeAppealProperty = target;
  const st = extractStreetName(target.address);
  const rate = meta.rateNum || 6.527;
  const eqRatio = meta.equalizationRatio || 33.3;

  // Default interior specs based on property type
  if (target.propertyType === 'Two Family') {
    activeAppealSpecs = { bedrooms: '4', bathrooms: '2', sqft: '', condition: 'average' };
  } else if (target.propertyType === 'Three Family') {
    activeAppealSpecs = { bedrooms: '6', bathrooms: '3', sqft: '', condition: 'average' };
  } else {
    activeAppealSpecs = { bedrooms: '3', bathrooms: '2', sqft: '', condition: 'average' };
  }

  // Chapter 123 Corridor (NJ Standard: ±15% of equalization ratio)
  const corridorLower = +(eqRatio * 0.85).toFixed(1);
  const corridorUpper = +(eqRatio * 1.15).toFixed(1);

  // Find comparables: Prioritize same street and same propertyType
  let streetComps = props.filter(p =>
    p.id !== target.id &&
    extractStreetName(p.address).toLowerCase() === st.toLowerCase() &&
    p.propertyType === target.propertyType
  );

  // If fewer than 3, widen to same street any type, then to same neighborhood and same type
  if (streetComps.length < 3) {
    streetComps = props.filter(p =>
      p.id !== target.id &&
      extractStreetName(p.address).toLowerCase() === st.toLowerCase()
    );
  }
  if (streetComps.length < 3) {
    streetComps = props.filter(p =>
      p.id !== target.id &&
      p.neighborhood === target.neighborhood &&
      p.propertyType === target.propertyType
    );
  }

  // Calculate median assessment among comps (exact statistical median)
  let compMedianAssess = target.assessedTotal;
  if (streetComps.length > 0) {
    const assessList = streetComps.map(c => c.assessedTotal).sort((a, b) => a - b);
    const mid = Math.floor(assessList.length / 2);
    compMedianAssess = assessList.length % 2 !== 0
      ? assessList[mid]
      : Math.round((assessList[mid - 1] + assessList[mid]) / 2);
  }

  // Sort comps by how well they represent the prevailing street baseline:
  // 1. Closeness to the street median assessment
  // 2. Bonus for verified deed sales
  streetComps.sort((a, b) => {
    const distA = Math.abs(a.assessedTotal - compMedianAssess);
    const distB = Math.abs(b.assessedTotal - compMedianAssess);
    const scoreA = distA * (a.salePrice > 50000 ? 0.85 : 1.0);
    const scoreB = distB * (b.salePrice > 50000 ? 0.85 : 1.0);
    return scoreA - scoreB;
  });

  // Pick top 5 representative comps
  const topComps = streetComps.slice(0, 5);

  const assessDiff = target.assessedTotal - compMedianAssess;
  const assessDiffPct = compMedianAssess > 0 ? (assessDiff / compMedianAssess) * 100 : 0;
  const potentialSavings = assessDiff > 0 ? (assessDiff / 100) * rate : 0;

  activeAppealComps = topComps;
  activeAppealMedian = compMedianAssess;
  activeAppealDiff = assessDiff;
  activeAppealDiffPct = assessDiffPct;

  // Chapter 123 Sale Ratio Check
  const hasRecentSale = target.salePrice > 50000;
  const saleRatio = hasRecentSale ? (target.assessedTotal / target.salePrice) * 100 : 0;
  const isCh123OverAssessed = hasRecentSale && saleRatio > corridorUpper;

  // Verdict Determination
  let verdictClass = 'verdict-moderate';
  let verdictBadge = 'Moderate / Fairly Assessed';
  let verdictIcon = '⚖️';
  let verdictDesc = '';

  if (isCh123OverAssessed) {
    verdictClass = 'verdict-strong';
    verdictBadge = 'Statutory Over-Assessment (NJ Ch. 123)';
    verdictIcon = '🚨';
    verdictDesc = `Your assessment-to-sale ratio is <strong>${saleRatio.toFixed(1)}%</strong>, which exceeds the statutory upper corridor (${corridorUpper}%). Under N.J.S.A. 54:51A-6, the County Tax Board is statutorily mandated to reduce your assessment to the common level ratio (${eqRatio.toFixed(1)}%). Your potential tax reduction is up to <strong>${formatUSD(potentialSavings)} / year</strong>.`;
  } else if (assessDiffPct >= 8.0) {
    verdictClass = 'verdict-strong';
    verdictBadge = 'High Likelihood of Appeal Success';
    verdictIcon = '🚨';
    verdictDesc = `Your assessment of ${formatUSDWhole(target.assessedTotal)} is <strong>${assessDiffPct.toFixed(1)}% higher</strong> than the prevailing median of comparable homes on ${escapeHtml(st)} (${formatUSDWhole(compMedianAssess)}). If successfully equalized to the street benchmark, your annual property tax could decrease by up to <strong>${formatUSD(potentialSavings)} / year</strong>.`;
  } else if (assessDiffPct <= -5.0) {
    verdictClass = 'verdict-low';
    verdictBadge = 'Favorable Assessment (Appeal Not Recommended)';
    verdictIcon = '🛡️';
    verdictDesc = `Your assessment of ${formatUSDWhole(target.assessedTotal)} is <strong>${Math.abs(assessDiffPct).toFixed(1)}% below</strong> the street comparable median (${formatUSDWhole(compMedianAssess)}). Filing an appeal carries a risk of counter-examination by the municipal tax assessor.`;
  } else {
    verdictClass = 'verdict-moderate';
    verdictBadge = 'Market Aligned / Borderline';
    verdictIcon = '✓';
    verdictDesc = `Your assessment of ${formatUSDWhole(target.assessedTotal)} closely aligns (within ${assessDiffPct.toFixed(1)}%) with street comparables (${formatUSDWhole(compMedianAssess)}). An appeal may succeed if your home has documented condition defects or obsolescence.`;
  }

  const titleEl = document.getElementById('appeal-dialog-title');
  const subEl = document.getElementById('appeal-dialog-subtitle');
  const contentEl = document.getElementById('appeal-dialog-content');

  if (titleEl) titleEl.innerHTML = `<span>${verdictIcon}</span> Tax Appeal Analysis: ${escapeHtml(target.address)}`;
  if (subEl) subEl.textContent = `Block ${target.block}, Lot ${target.lot} • ${meta.name} (District ${meta.districtCode}) • Certified Tax Rate: ${meta.certifiedTaxRate}`;

  const savingsDisplay = potentialSavings > 0
    ? `<strong style="font-size: 1.15rem; color: #dc2626;">${formatUSD(potentialSavings)} / yr</strong>`
    : `<strong style="font-size: 0.95rem; color: #16a34a;">None (Favorable Assessment)</strong>`;

  if (contentEl) {
    contentEl.innerHTML = `
      <!-- Verdict Card -->
      <div class="appeal-verdict-card ${verdictClass}">
        <div class="verdict-top-bar">
          <span class="verdict-badge">${verdictIcon} ${verdictBadge}</span>
          <span style="font-weight: 700; font-size: 0.9rem;">Potential Tax Reduction: ${savingsDisplay}</span>
        </div>
        <p style="margin: 0; font-size: 0.92rem; line-height: 1.55;">${verdictDesc}</p>
        <div class="verdict-stat-grid">
          <div class="verdict-stat-item">
            <span class="verdict-stat-lbl">Your Total Assessment</span>
            <span class="verdict-stat-val">${formatUSDWhole(target.assessedTotal)}</span>
            <span class="verdict-stat-sub">Land: ${formatUSDWhole(target.assessedLand || 0)} • Bldg: ${formatUSDWhole(target.assessedBuilding || 0)}</span>
          </div>
          <div class="verdict-stat-item">
            <span class="verdict-stat-lbl">Street Comps Median</span>
            <span class="verdict-stat-val">${formatUSDWhole(compMedianAssess)}</span>
            <span class="verdict-stat-sub">Based on ${streetComps.length} similar ${escapeHtml(target.propertyType)} homes</span>
          </div>
          <div class="verdict-stat-item">
            <span class="verdict-stat-lbl">Implied Market Value</span>
            <span class="verdict-stat-val">${formatUSDWhole(target.estimatedMarketValue)}</span>
            <span class="verdict-stat-sub">At ${eqRatio.toFixed(1)}% Equalization Ratio</span>
          </div>
          <div class="verdict-stat-item">
            <span class="verdict-stat-lbl">NJ Ch. 123 Statutory Ratio</span>
            <span class="verdict-stat-val">${eqRatio.toFixed(1)}%</span>
            <span class="verdict-stat-sub">Corridor: ${corridorLower}% to ${corridorUpper}%</span>
          </div>
        </div>
      </div>

      <!-- Attorney Consultation Monetization Callout -->
      <div class="appeal-attorney-cta-card">
        <div class="attorney-cta-header">
          <span class="attorney-cta-badge">⭐ Recommended Next Step</span>
          <span class="attorney-cta-deadline">April 1 County Deadline</span>
        </div>
        <div class="attorney-cta-body">
          <h4 class="attorney-cta-title">Request Free Contingency Review from a Licensed NJ Property Tax Appeal Attorney</h4>
          <p class="attorney-cta-desc">
            In New Jersey, property tax appeal attorneys work on a <strong>pure contingency basis</strong>: you pay zero upfront out-of-pocket legal fees, and the attorney is only paid a percentage of the actual property tax reduction won for you. Have a certified NJ tax attorney review your Block ${escapeHtml(target.block)}, Lot ${escapeHtml(target.lot)} assessment and street comparables.
          </p>
          <div class="attorney-cta-perks">
            <span>✓ 100% Free &amp; Confidential Case Evaluation</span>
            <span>✓ Licensed before ${escapeHtml(meta.countyShort)} Board of Taxation &amp; NJ Tax Court</span>
            <span>✓ No Reduction = Zero Legal Fees</span>
          </div>
        </div>
        <div class="attorney-cta-action">
          <button type="button" class="btn-attorney-review-trigger" onclick="openAttorneyConsultModal()">
            <span>⚖️</span> Request Free Attorney Review ➔
          </button>
        </div>
      </div>

      <!-- Home Details & Interior Specs (Form A-1 Refinement) -->
      <div class="appeal-refine-box">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; flex-wrap: wrap;">
          <div>
            <h4 style="margin: 0 0 4px; font-size: 0.96rem; font-weight: 800; color: #0f172a; display: flex; align-items: center; gap: 6px;">
              <span>🏡</span> Home Details &amp; Interior Specifications (Form A-1 Refinement)
            </h4>
            <p style="margin: 0; font-size: 0.8rem; color: #64748b; line-height: 1.45;">
              Public MOD-IV tax records hold exterior data (Style: <strong>${escapeHtml(target.bldgDesc || target.propertyType)}</strong>, Lot: <strong>${escapeHtml(target.lotSize || (target.acres ? target.acres + ' AC' : 'Standard'))}</strong>, Built: <strong>${target.yearBuilt > 0 ? target.yearBuilt : '—'}</strong>). Select your home's verified interior details to generate room-level arguments for County Tax Commissioners.
            </p>
          </div>
          <span class="spec-metric-pill highlight">NJ Form A-1 Section VI</span>
        </div>

        <div class="appeal-spec-grid">
          <div class="appeal-spec-field">
            <label class="appeal-spec-label" for="appeal-spec-beds">Bedrooms</label>
            <select id="appeal-spec-beds" class="appeal-spec-select" onchange="updateAppealInteriorSpecs()">
              <option value="1" ${activeAppealSpecs.bedrooms === '1' ? 'selected' : ''}>1 Bedroom</option>
              <option value="2" ${activeAppealSpecs.bedrooms === '2' ? 'selected' : ''}>2 Bedrooms</option>
              <option value="3" ${activeAppealSpecs.bedrooms === '3' ? 'selected' : ''}>3 Bedrooms</option>
              <option value="4" ${activeAppealSpecs.bedrooms === '4' ? 'selected' : ''}>4 Bedrooms</option>
              <option value="5" ${activeAppealSpecs.bedrooms === '5' ? 'selected' : ''}>5 Bedrooms</option>
              <option value="6+" ${activeAppealSpecs.bedrooms === '6+' ? 'selected' : ''}>6+ Bedrooms</option>
            </select>
          </div>

          <div class="appeal-spec-field">
            <label class="appeal-spec-label" for="appeal-spec-baths">Bathrooms</label>
            <select id="appeal-spec-baths" class="appeal-spec-select" onchange="updateAppealInteriorSpecs()">
              <option value="1" ${activeAppealSpecs.bathrooms === '1' ? 'selected' : ''}>1.0 Bath</option>
              <option value="1.5" ${activeAppealSpecs.bathrooms === '1.5' ? 'selected' : ''}>1.5 Baths</option>
              <option value="2" ${activeAppealSpecs.bathrooms === '2' ? 'selected' : ''}>2.0 Baths</option>
              <option value="2.5" ${activeAppealSpecs.bathrooms === '2.5' ? 'selected' : ''}>2.5 Baths</option>
              <option value="3" ${activeAppealSpecs.bathrooms === '3' ? 'selected' : ''}>3.0 Baths</option>
              <option value="3.5" ${activeAppealSpecs.bathrooms === '3.5' ? 'selected' : ''}>3.5 Baths</option>
              <option value="4+" ${activeAppealSpecs.bathrooms === '4+' ? 'selected' : ''}>4.0+ Baths</option>
            </select>
          </div>

          <div class="appeal-spec-field">
            <label class="appeal-spec-label" for="appeal-spec-sqft">Est. Finished Sq Ft</label>
            <input type="number" id="appeal-spec-sqft" class="appeal-spec-input" placeholder="e.g. 1650" min="300" max="25000" value="${escapeHtml(activeAppealSpecs.sqft || '')}" oninput="updateAppealInteriorSpecs()">
          </div>

          <div class="appeal-spec-field" style="grid-column: span 2;">
            <label class="appeal-spec-label" for="appeal-spec-condition">Condition / Physical Obsolescence</label>
            <select id="appeal-spec-condition" class="appeal-spec-select" onchange="updateAppealInteriorSpecs()">
              <option value="average" ${activeAppealSpecs.condition === 'average' ? 'selected' : ''}>Standard / Maintained (Comparable to Street)</option>
              <option value="dated" ${activeAppealSpecs.condition === 'dated' ? 'selected' : ''}>Unrenovated / Original (Dated Kitchen/Baths)</option>
              <option value="deferred" ${activeAppealSpecs.condition === 'deferred' ? 'selected' : ''}>Deferred Maintenance / Major Structural Repairs</option>
              <option value="renovated" ${activeAppealSpecs.condition === 'renovated' ? 'selected' : ''}>Recently Renovated / Modernized</option>
            </select>
          </div>
        </div>

        <div class="appeal-spec-metrics">
          <span class="spec-metric-pill" id="appeal-metric-per-bed">Bldg Assess / Bed: $${Math.round((target.assessedBuilding || target.assessedTotal) / (parseInt(activeAppealSpecs.bedrooms, 10) || 1)).toLocaleString()}</span>
          <span class="spec-metric-pill" id="appeal-metric-per-sqft" style="display: ${activeAppealSpecs.sqft ? 'inline-flex' : 'none'};">Bldg / Sq Ft: $${activeAppealSpecs.sqft ? ((target.assessedBuilding || target.assessedTotal) / parseInt(activeAppealSpecs.sqft, 10)).toFixed(2) : ''}</span>
          <span class="spec-metric-pill">MOD-IV Style: ${escapeHtml(target.bldgDesc || 'Class 2')}</span>
          <span class="spec-metric-pill">Built: ${target.yearBuilt > 0 ? target.yearBuilt : 'N/A'}</span>
        </div>
      </div>

      <!-- Street Comparables Table -->
      <div>
        <div style="display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px;">
          <h4 style="margin: 0; font-size: 1rem; font-weight: 800; color: #0f172a;">Official MOD-IV Street Comparables (${escapeHtml(st)})</h4>
          <span style="font-size: 0.78rem; color: var(--text-subtle);">Official ${escapeHtml(meta.countyShort)} District ${meta.districtCode} Roll</span>
        </div>
        <div class="appeal-comps-table-wrapper">
          <table class="appeal-comps-table">
            <thead>
              <tr>
                <th>Property</th>
                <th>Block / Lot</th>
                <th>Type</th>
                <th>Year</th>
                <th>Land Val</th>
                <th>Bldg Val</th>
                <th>Net Assessed</th>
                <th>2026 Annual Tax</th>
                <th>Deed Sale Record</th>
              </tr>
            </thead>
            <tbody>
              <tr class="subject-property-row">
                <td><strong>★ ${escapeHtml(target.address)} (Subject)</strong></td>
                <td>B:${escapeHtml(target.block)} L:${escapeHtml(target.lot)}</td>
                <td>${escapeHtml(target.propertyType)}</td>
                <td>${target.yearBuilt > 0 ? target.yearBuilt : '—'}</td>
                <td>${formatUSDWhole(target.assessedLand || 0)}</td>
                <td>${formatUSDWhole(target.assessedBuilding || 0)}</td>
                <td><strong>${formatUSDWhole(target.assessedTotal)}</strong></td>
                <td style="color: #dc2626; font-weight: 800;">${formatUSD(target.annualTax)}</td>
                <td>${target.salePrice > 100 ? `${formatUSDWhole(target.salePrice)} (${target.deedDate || ''})` : '—'}</td>
              </tr>
              ${topComps.map(c => `
                <tr>
                  <td><strong>${escapeHtml(c.address)}</strong></td>
                  <td>B:${escapeHtml(c.block)} L:${escapeHtml(c.lot)}</td>
                  <td>${escapeHtml(c.propertyType)}</td>
                  <td>${c.yearBuilt > 0 ? c.yearBuilt : '—'}</td>
                  <td>${formatUSDWhole(c.assessedLand || 0)}</td>
                  <td>${formatUSDWhole(c.assessedBuilding || 0)}</td>
                  <td><strong>${formatUSDWhole(c.assessedTotal)}</strong></td>
                  <td>${formatUSD(c.annualTax)}</td>
                  <td>${c.salePrice > 100 ? `${formatUSDWhole(c.salePrice)} (${c.deedDate || ''})` : '—'}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      </div>

      <!-- Form A-1 Evidence Format -->
      <div class="form-a1-evidence-box">
        <div class="form-a1-header">
          <h4>📋 Formatted Comparable Evidence for NJ Form A-1 (County Tax Board Appeal)</h4>
          <span style="font-size: 0.76rem; color: #475569;">Ready to attach to your petition</span>
        </div>
        <div class="form-a1-text" id="form-a1-text-block">${escapeHtml(renderAppealEvidenceText())}</div>
      </div>

      <!-- Filing Guidance & Deadlines -->
      <div style="background: #f1f5f9; border-radius: 8px; padding: 14px 18px; font-size: 0.84rem; color: #334155; line-height: 1.55;">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 8px; margin-bottom: 8px;">
          <strong style="color: #0f172a; font-size: 0.92rem;">📅 ${escapeHtml(meta.countyBoardName || meta.county + ' Board of Taxation')} Form A-1 Appeal Checklist:</strong>
          <a href="https://www.state.nj.us/treasury/taxation/pdf/other_forms/lpt/ptappeal.pdf" target="_blank" rel="noopener" class="btn-jump-action" style="padding: 4px 10px; font-size: 0.78rem; background: #2563eb; color: #fff; text-decoration: none; border-radius: 6px; font-weight: 700;">
            <span>📥</span> Download Official Form A-1 (PDF) ↗
          </a>
        </div>
        • <strong>Filing Office:</strong> ${escapeHtml(meta.countyBoardName || meta.county + ' Board of Taxation')}.<br>
        • <strong>Statutory Deadlines:</strong> Annually on or before <strong>April 1</strong> (extended to <strong>May 1</strong> in citywide revaluation years under N.J.S.A. 54:3-21).<br>
        • <strong>Filing Fees:</strong> $5.00 (&lt;$150k assessment), $25.00 ($150k–$500k), $100.00 ($500k–$1M), $150.00 (&gt;$1M), payable to County Tax Administrator.<br>
        • <strong>Service Requirement:</strong> 1 copy served on County Tax Board, 1 copy on ${escapeHtml(meta.name)} Municipal Tax Assessor, and 1 copy on ${escapeHtml(meta.name)} Municipal Clerk.<br>
        • <strong>Current Taxes Paid:</strong> Under N.J.S.A. 54:3-27, all municipal taxes and sewer charges must be paid current to have an appeal heard.<br>
        • <strong>Direct County Verification:</strong> <a href="javascript:void(0)" onclick="openMod4VerificationModal('${escapeHtml(target.id)}')" style="font-weight: 700; color: #2563eb; text-decoration: underline;">Inspect Certified MOD-IV Duplicate Record &amp; County Portals ➔</a>
      </div>
    `;
  }

  if (dialog && typeof dialog.showModal === 'function') {
    dialog.showModal();
  }
}

function copyAppealEvidence() {
  const el = document.getElementById('form-a1-text-block');
  if (el) {
    navigator.clipboard.writeText(el.textContent).then(() => {
      showToast('✓ Form A-1 evidence table copied to clipboard!');
    }).catch(() => {
      showToast('Copied to clipboard');
    });
  }
}

function printAppealEvidence() {
  const printContainer = document.getElementById('printable-form-a1-packet');
  if (!printContainer || !activeAppealProperty) {
    window.print();
    return;
  }

  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;
  const target = activeAppealProperty;
  const comps = activeAppealComps || [];
  const eqRatio = meta.equalizationRatio ? parseFloat(meta.equalizationRatio) : 100.0;
  const corridorLower = (eqRatio * 0.85).toFixed(2);
  const corridorUpper = (eqRatio * 1.15).toFixed(2);
  const rate = parseFloat(meta.certifiedTaxRate) || 2.5;

  const targetDiff = (activeAppealMedian && target.assessedTotal > activeAppealMedian)
    ? (target.assessedTotal - activeAppealMedian)
    : 0;
  const estSavings = Math.round((targetDiff / 100) * rate);

  printContainer.innerHTML = `
    <div class="print-form-a1-sheet">
      <div class="print-a1-header-block">
        <div class="print-a1-state-seal">STATE OF NEW JERSEY • COUNTY BOARD OF TAXATION</div>
        <h2 class="print-a1-title">PETITION OF APPEAL (FORM A-1) — COMPARABLE SALES EVIDENCE SCHEDULE</h2>
        <div class="print-a1-statute">Statutory Standard: N.J.S.A. 54:3-21 et seq., N.J.A.C. 18:12A-1.6 &amp; N.J.S.A. 54:51A-6 (Chapter 123)</div>
        <div class="print-a1-source-strip">
          <span>Prepared via <strong>MyTownLens</strong> (mytownlens.com)</span>
          <span>Date Generated: ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}</span>
        </div>
      </div>

      <div class="print-a1-sec-header">SECTION I: SUBJECT PROPERTY &amp; TAXING DISTRICT PARTICULARS</div>
      <table class="print-a1-grid-table">
        <tr>
          <th>County Board:</th>
          <td>${escapeHtml(meta.countyBoardName || meta.county + ' Board of Taxation')}</td>
          <th>Taxing District:</th>
          <td>${escapeHtml(meta.name)} (District Code ${meta.districtCode})</td>
        </tr>
        <tr>
          <th>Subject Address:</th>
          <td><strong>${escapeHtml(target.address)}</strong></td>
          <th>Block &amp; Lot:</th>
          <td><strong>Block ${escapeHtml(target.block)}, Lot ${escapeHtml(target.lot)}</strong></td>
        </tr>
        <tr>
          <th>Property Class:</th>
          <td>Class 2 (Residential 1-4 Family)</td>
          <th>Building Style / Year:</th>
          <td>${escapeHtml(target.bldgDesc || target.propertyType || 'Class 2')} (Built: ${target.yearBuilt > 0 ? target.yearBuilt : '—'})</td>
        </tr>
        <tr>
          <th>Current Assessment:</th>
          <td>Land: $${(target.assessedLand || 0).toLocaleString()} • Bldg: $${(target.assessedBuilding || 0).toLocaleString()} • <strong>Total: $${target.assessedTotal.toLocaleString()}</strong></td>
          <th>Annual Property Tax:</th>
          <td><strong>$${target.annualTax.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</strong> (Rate: ${meta.certifiedTaxRate})</td>
        </tr>
      </table>

      <div class="print-a1-sec-header">SECTION II: CHAPTER 123 STATUTORY RATIO CORRIDOR ANALYSIS</div>
      <table class="print-a1-grid-table">
        <tr>
          <th>Director's Common Level Ratio:</th>
          <td><strong>${eqRatio.toFixed(2)}%</strong></td>
          <th>Statutory Ratio Corridor (±15%):</th>
          <td><strong>${corridorLower}% to ${corridorUpper}%</strong></td>
        </tr>
        <tr>
          <th>Street Median Comparable Assessment:</th>
          <td><strong>$${(activeAppealMedian || target.assessedTotal).toLocaleString()}</strong></td>
          <th>Indicated Over-Assessment:</th>
          <td><strong>${activeAppealDiffPct ? activeAppealDiffPct.toFixed(1) + '%' : '0.0%'}</strong> ($${Math.max(0, activeAppealDiff || 0).toLocaleString()})</td>
        </tr>
      </table>

      <div class="print-a1-sec-header">SECTION III: VERIFIED MOD-IV COMPARABLE ARMS-LENGTH SALES SCHEDULE</div>
      <table class="print-a1-comps-sheet">
        <thead>
          <tr>
            <th>#</th>
            <th>Comparable Property Address</th>
            <th>Block / Lot</th>
            <th>Deed Date</th>
            <th>Deed Book / Page</th>
            <th>Sale Price ($)</th>
            <th>Assessed Value ($)</th>
            <th>Ratio (%)</th>
          </tr>
        </thead>
        <tbody>
          ${comps.map((c, i) => `
            <tr>
              <td><strong>${i + 1}</strong></td>
              <td><strong>${escapeHtml(c.address)}</strong></td>
              <td>B:${escapeHtml(c.block)} L:${escapeHtml(c.lot)}</td>
              <td>${escapeHtml(c.deedDate || 'MOD-IV Record')}</td>
              <td>${escapeHtml(c.deedBookPage || 'Recorded Deed')}</td>
              <td><strong>$${(c.salePrice || 0).toLocaleString()}</strong></td>
              <td>$${(c.assessedTotal || 0).toLocaleString()}</td>
              <td>${c.salePrice > 50000 ? ((c.assessedTotal / c.salePrice) * 100).toFixed(1) + '%' : '—'}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>

      <div class="print-a1-sec-header">SECTION IV: REQUESTED VALUATION &amp; RELIEF SUMMARY</div>
      <div class="print-a1-summary-box">
        <p>Pursuant to N.J.S.A. 54:51A-6 (Chapter 123), when the ratio of assessed value to true value exceeds the upper corridor limit (${corridorUpper}%), the County Board of Taxation shall revise the assessment by applying the common level ratio (${eqRatio.toFixed(2)}%) to the equalized true market value.</p>
        <div class="print-a1-relief-row">
          <span>Petitioner Requested Total Assessment:</span>
          <strong>$${(activeAppealMedian || target.assessedTotal).toLocaleString()}</strong>
        </div>
        <div class="print-a1-relief-row">
          <span>Projected Annual Property Tax Reduction:</span>
          <strong style="color: #059669;">$${estSavings.toLocaleString()} / year</strong>
        </div>
      </div>

      <div class="print-a1-footer-sign-strip">
        <div class="print-sign-cell">
          <div class="print-sign-rule"></div>
          <div>Signature of Petitioner / Taxpayer / Attorney of Record</div>
        </div>
        <div class="print-sign-cell">
          <div class="print-sign-rule"></div>
          <div>Date Filed with County Board of Taxation</div>
        </div>
      </div>
    </div>
  `;

  document.body.classList.add('printing-a1-packet');
  window.print();
  window.addEventListener('afterprint', () => {
    document.body.classList.remove('printing-a1-packet');
  }, { once: true });
}

// ==========================================================================
// MONETIZATION FEATURE 1: ⚖️ Free Attorney Review Request (Golden Lead Dossier)
// ==========================================================================
let latestSubmittedLead = null;
let activeInspectedDossier = null;

function buildFormattedLeadDossier(type, record) {
  if (!record) return '';

  if (type === 'appeals') {
    const p = record.property || {};
    const c = record.contact || {};
    const m = record.caseMerits || {};
    const comps = Array.isArray(record.comparables) ? record.comparables : [];
    const specs = m.interiorSpecs || {};
    const savings = m.potentialAnnualSavings !== undefined
      ? m.potentialAnnualSavings
      : Math.round((Number(p.annualTax) || 0) * 0.15);
    const overAssess = m.indicatedOverAssessment !== undefined
      ? m.indicatedOverAssessment
      : Math.round((Number(p.assessedTotal) || 0) * 0.12);
    const overPct = m.overAssessmentPct !== undefined ? m.overAssessmentPct : 12.0;

    const compLines = comps.length > 0
      ? comps.map((comp, idx) =>
        `  ${idx + 1}. ${comp.address} (Block ${comp.block}, Lot ${comp.lot}) | Assessed: $${Number(comp.assessedTotal || 0).toLocaleString()} | Tax: $${Number(comp.annualTax || 0).toLocaleString()} | Sale: ${comp.salePrice > 100 ? '$' + Number(comp.salePrice).toLocaleString() + ' (' + (comp.deedDate || 'Recorded') + ')' : 'MOD-IV Comparable'}`
      ).join('\n')
      : '  (Verified against municipal street baseline in MOD-IV roll)';

    return [
      '========================================================================',
      'MYTOWNLENS — PRE-QUALIFIED NJ PROPERTY TAX APPEAL CASE DOSSIER',
      '========================================================================',
      `Lead Ticket ID:      ${record.id || 'N/A'}`,
      `Submitted Timestamp: ${record.submittedAt || new Date().toISOString()}`,
      `Filing Jurisdiction: ${p.county || 'New Jersey'} County Board of Taxation (Statutory April 1 Deadline)`,
      '',
      '1. HOMEOWNER CONTACT & REPRESENTATION CONSENT',
      '------------------------------------------------------------------------',
      `Homeowner Name:      ${c.name || '—'}`,
      `Phone Number:        ${c.phone || '—'}`,
      `Email Address:       ${c.email || '—'}`,
      `Preferred Contact:   ${(c.preferredContact || 'phone').toUpperCase()}`,
      `Legal Owner Verified:${c.isLegalOwner !== false ? ' YES (Confirmed Legal Owner / Taxpayer)' : ' Pending Verification'}`,
      `Homeowner Notes:     ${c.notes || 'None provided'}`,
      '',
      '2. CERTIFIED MOD-IV SUBJECT PARCEL PROFILE',
      '------------------------------------------------------------------------',
      `Property Address:    ${p.address || '—'}`,
      `Municipality:        ${p.municipality || '—'} (${p.county || ''} County • District ${p.districtCode || '—'})`,
      `Block / Lot / PIN:   Block ${p.block || '—'}, Lot ${p.lot || '—'} (PAMS PIN: ${p.pamsPin || `${p.districtCode || ''}_${p.block || ''}_${p.lot || ''}`})`,
      `Property Class:      Class 2 Residential (${p.propertyType || p.bldgDesc || 'Residential'}) • Built: ${p.yearBuilt || '—'}`,
      `Current Assessment:  Land: $${Number(p.assessedLand || 0).toLocaleString()} | Bldg: $${Number(p.assessedBuilding || 0).toLocaleString()} | TOTAL: $${Number(p.assessedTotal || 0).toLocaleString()}`,
      `Certified Tax Rate:  ${p.certifiedTaxRate || '—'}`,
      `2026 Annual Tax:     $${Number(p.annualTax || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`,
      `Implied Market Val:  $${Number(p.estimatedMarketValue || 0).toLocaleString()}`,
      '',
      '3. CHAPTER 123 & COMPARABLE OVER-ASSESSMENT MERITS',
      '------------------------------------------------------------------------',
      `Ch. 123 Equal. Ratio:${m.equalizationRatio ? m.equalizationRatio + '% (Corridor: ' + m.corridorLower + '% – ' + m.corridorUpper + '%)' : 'Certified County Ratio'}`,
      `Street Comps Median: $${Number(m.streetMedianAssessment || p.assessedTotal || 0).toLocaleString()}`,
      `Indicated Variance:  +$${Number(overAssess).toLocaleString()} (+${Number(overPct).toFixed(1)}% Over-Assessed vs. Street Benchmark)`,
      `EST. TAX SAVINGS:    $${Number(savings).toLocaleString()} / YEAR (Contingency Case Value)`,
      `Interior Form A-1:   ${specs.bedrooms || '3'} Beds • ${specs.bathrooms || '2'} Baths • ${specs.sqft ? specs.sqft + ' SqFt' : 'Std SqFt'} • Condition: ${specs.condition || 'average'}`,
      '',
      `4. VERIFIED MOD-IV STREET COMPARABLES ATTACHED (${comps.length} PARCELS)`,
      '------------------------------------------------------------------------',
      compLines,
      '========================================================================'
    ].join('\n');
  }

  if (type === 'realtor') {
    const p = record.property || {};
    const c = record.contact || {};
    return [
      '========================================================================',
      'MYTOWNLENS — PRE-QUALIFIED HOMEOWNER VALUATION & CMA LISTING LEAD',
      '========================================================================',
      `Lead Ticket ID:      ${record.id || 'N/A'}`,
      `Submitted Timestamp: ${record.submittedAt || new Date().toISOString()}`,
      '',
      '1. HOMEOWNER CONTACT & TIMELINE',
      '------------------------------------------------------------------------',
      `Homeowner Name:      ${c.name || '—'}`,
      `Phone Number:        ${c.phone || '—'}`,
      `Email Address:       ${c.email || '—'}`,
      `Selling Timeline:    ${(c.timeline || 'curious').replace(/_/g, ' ').toUpperCase()}`,
      `Interior / Upgrades: ${c.notes || 'Standard residential configuration'}`,
      '',
      '2. PROPERTY VALUATION & MOD-IV PROFILE',
      '------------------------------------------------------------------------',
      `Property Address:    ${p.address || '—'}`,
      `Municipality:        ${p.municipality || '—'} (${p.county || ''} County)`,
      `Block & Lot:         Block ${p.block || '—'}, Lot ${p.lot || '—'}`,
      `Est. Market Value:   $${Number(p.estimatedMarketValue || 450000).toLocaleString()}`,
      '========================================================================'
    ].join('\n');
  }

  return JSON.stringify(record, null, 2);
}

function openAttorneyConsultModal() {
  const modal = document.getElementById('attorney-consult-dialog');
  if (!modal) return;

  const target = activeAppealProperty || (propertyAssessmentsData?.properties?.[0] || null);
  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;
  const badgeEl = document.getElementById('attorney-lead-prop-badge');
  const rate = parseFloat(meta.certifiedTaxRate) || meta.rateNum || 2.5;
  const eqRatio = parseFloat(meta.equalizationRatio) || 100.0;
  const diff = (activeAppealMedian && target && target.assessedTotal > activeAppealMedian)
    ? (target.assessedTotal - activeAppealMedian)
    : (activeAppealDiff > 0 ? activeAppealDiff : Math.round((target?.assessedTotal || 180000) * 0.12));
  const compMedian = activeAppealMedian || (target ? target.assessedTotal - diff : 0);
  const diffPct = compMedian > 0 ? (diff / compMedian) * 100 : 12.0;
  const potentialSavings = Math.max(250, Math.round((diff / 100) * rate));
  const compsCount = Array.isArray(activeAppealComps) && activeAppealComps.length > 0 ? activeAppealComps.length : 5;

  if (badgeEl && target) {
    badgeEl.innerHTML = `
      <div class="lead-badge-header">
        <span class="lead-badge-pin">📍 ${escapeHtml(target.address)} <small style="font-weight:600; color:#475569;">(Block ${escapeHtml(target.block)}, Lot ${escapeHtml(target.lot)})</small></span>
        <span class="lead-badge-savings">Est. Tax Savings: <strong>$${potentialSavings.toLocaleString()} / yr</strong></span>
      </div>
      <div class="lead-badge-sub" style="display: flex; flex-wrap: wrap; gap: 6px 14px; margin-top: 6px;">
        <span>🏛️ <strong>${escapeHtml(meta.name)}</strong> (${escapeHtml(meta.countyShort)})</span>
        <span>📊 Assessment: <strong>$${target.assessedTotal.toLocaleString()}</strong> vs. Street Median: <strong>$${compMedian.toLocaleString()}</strong></span>
        <span style="color:#b91c1c; font-weight:700;">⚖️ Over-Assessed: +$${diff.toLocaleString()} (+${diffPct.toFixed(1)}%)</span>
        <span style="color:#047857; font-weight:700;">✓ ${compsCount} Verified MOD-IV Comps &amp; Ch. 123 (${eqRatio.toFixed(1)}%) Attached</span>
      </div>
    `;
  }

  const form = document.getElementById('attorney-lead-form');
  const success = document.getElementById('attorney-lead-success');
  if (form) {
    form.reset();
    form.querySelectorAll('[aria-invalid]').forEach(el => el.setAttribute('aria-invalid', 'false'));
    form.style.display = 'block';
  }
  if (success) success.style.display = 'none';

  if (typeof modal.showModal === 'function') {
    modal.showModal();
  } else {
    modal.setAttribute('open', '');
  }
}

function closeAttorneyConsultModal() {
  const modal = document.getElementById('attorney-consult-dialog');
  if (!modal) return;
  if (typeof modal.close === 'function') {
    modal.close();
  } else {
    modal.removeAttribute('open');
  }
}

function handleAttorneyLeadSubmit(e) {
  e.preventDefault();
  const target = activeAppealProperty || (propertyAssessmentsData?.properties?.[0] || {});
  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;

  const name = document.getElementById('lead-full-name')?.value?.trim() || '';
  const phone = document.getElementById('lead-phone')?.value?.trim() || '';
  const email = document.getElementById('lead-email')?.value?.trim() || '';
  const pref = document.getElementById('lead-pref-contact')?.value || 'phone';
  const notes = document.getElementById('lead-notes')?.value?.trim() || '';
  const isLegalOwner = document.getElementById('lead-is-owner') ? document.getElementById('lead-is-owner').checked : true;

  const rate = parseFloat(meta.certifiedTaxRate) || meta.rateNum || 2.5;
  const eqRatio = parseFloat(meta.equalizationRatio) || 100.0;
  const corridorLower = +(eqRatio * 0.85).toFixed(1);
  const corridorUpper = +(eqRatio * 1.15).toFixed(1);

  const assessedTotal = Number(target?.assessedTotal) || 0;
  const compMedian = activeAppealMedian || Math.round(assessedTotal * 0.88);
  const diff = Math.max(0, assessedTotal - compMedian);
  const diffPct = compMedian > 0 ? +((diff / compMedian) * 100).toFixed(1) : 12.0;
  const potentialSavings = diff > 0 ? Math.round((diff / 100) * rate) : Math.round((Number(target?.annualTax) || 0) * 0.15);

  const compsPayload = Array.isArray(activeAppealComps) ? activeAppealComps.slice(0, 5).map(c => ({
    address: c.address || '',
    block: c.block || '',
    lot: c.lot || '',
    propertyType: c.propertyType || 'Single Family',
    yearBuilt: c.yearBuilt || 0,
    assessedTotal: c.assessedTotal || 0,
    annualTax: c.annualTax || 0,
    salePrice: c.salePrice || 0,
    deedDate: c.deedDate || ''
  })) : [];

  const leadRecord = {
    id: 'lead_' + Date.now(),
    submittedAt: new Date().toISOString(),
    property: {
      id: target?.id || '',
      address: target?.address || '',
      block: target?.block || '',
      lot: target?.lot || '',
      pamsPin: target?.pamsPin || `${meta.districtCode || ''}_${target?.block || ''}_${target?.lot || ''}`,
      propertyClass: '2',
      propertyType: target?.propertyType || 'Single Family',
      bldgDesc: target?.bldgDesc || 'Class 2 Residential',
      yearBuilt: target?.yearBuilt || 0,
      lotSize: target?.lotSize || '',
      assessedLand: target?.assessedLand || 0,
      assessedBuilding: target?.assessedBuilding || 0,
      assessedTotal: assessedTotal,
      certifiedTaxRate: meta.certifiedTaxRate || `${rate}%`,
      annualTax: target?.annualTax || 0,
      estimatedMarketValue: target?.estimatedMarketValue || 0,
      municipality: meta.name,
      county: meta.county,
      districtCode: meta.districtCode || ''
    },
    caseMerits: {
      equalizationRatio: eqRatio,
      corridorLower,
      corridorUpper,
      streetMedianAssessment: compMedian,
      indicatedOverAssessment: diff,
      overAssessmentPct: diffPct,
      potentialAnnualSavings: potentialSavings,
      interiorSpecs: activeAppealSpecs ? { ...activeAppealSpecs } : { bedrooms: '3', bathrooms: '2', sqft: '', condition: 'average' }
    },
    comparables: compsPayload,
    contact: { name, phone, email, preferredContact: pref, isLegalOwner, notes }
  };

  leadRecord.formattedDossier = buildFormattedLeadDossier('appeals', leadRecord);
  latestSubmittedLead = { type: 'appeals', record: leadRecord };

  try {
    const existing = JSON.parse(localStorage.getItem('mytownlens_attorney_leads') || '[]');
    existing.push(leadRecord);
    localStorage.setItem('mytownlens_attorney_leads', JSON.stringify(existing));
  } catch (err) {
    console.warn('LocalStorage lead save error:', err);
  }

  // Auto-forward full Golden Dossier to webhook if configured
  dispatchLeadWebhook('attorney_tax_appeal', leadRecord);

  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('mytownlens:attorney_lead_submitted', { detail: leadRecord }));
  }

  const form = document.getElementById('attorney-lead-form');
  const success = document.getElementById('attorney-lead-success');
  const addrEl = document.getElementById('lead-success-addr');
  const summaryEl = document.getElementById('lead-success-summary');

  if (form) form.style.display = 'none';
  if (addrEl && target) addrEl.textContent = target.address;
  if (summaryEl) {
    summaryEl.innerHTML = `
      <div style="font-size: 0.84rem; color: #334155; display: grid; gap: 5px;">
        <span><strong>Docket ID:</strong> <code>${escapeHtml(leadRecord.id)}</code> &bull; <strong>Owner Verified:</strong> ${isLegalOwner ? 'Yes ✓' : 'Pending'}</span>
        <span><strong>Applicant:</strong> ${escapeHtml(name)} (${escapeHtml(phone)} &bull; ${escapeHtml(email)})</span>
        <span><strong>Parcel:</strong> ${escapeHtml(target?.address || '')} (Block ${escapeHtml(target?.block || '')}, Lot ${escapeHtml(target?.lot || '')} • ${escapeHtml(meta.name)})</span>
        <span><strong>Indicated Over-Assessment:</strong> +$${diff.toLocaleString()} (+${diffPct}%) &bull; <strong style="color:#047857;">Est. Tax Savings: $${potentialSavings.toLocaleString()}/yr</strong></span>
        <span><strong>Evidence Attached:</strong> ${compsPayload.length} Verified MOD-IV Street Comparables &amp; Ch. 123 Corridor (${corridorLower}%–${corridorUpper}%)</span>
        <span><strong>Filing Jurisdiction:</strong> ${escapeHtml(meta.countyBoardName || meta.county + ' County Board of Taxation')}</span>
      </div>
    `;
  }
  if (success) success.style.display = 'block';
  showToast('✓ Pre-qualified attorney case docket created!');
}

function copyLatestSubmittedDossier(type) {
  if (!latestSubmittedLead || !latestSubmittedLead.record) {
    showToast('⚠️ No recent dossier to copy');
    return;
  }
  const text = latestSubmittedLead.record.formattedDossier || buildFormattedLeadDossier(type || latestSubmittedLead.type, latestSubmittedLead.record);
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      showToast('✓ Full Case Dossier copied to clipboard!');
    }).catch(() => {
      showToast('✓ Dossier copied');
    });
  }
}

