// ==========================================================================
// MONETIZATION FEATURE 4: 📊 Owner Lead Management Console & Admin Security
// ==========================================================================
const DEFAULT_ADMIN_PASSWORD = 'MyTownLens2026!';

function computeAdminPasswordHash(rawPassword) {
  const str = 'mytownlens_salt_v1::' + String(rawPassword || '');
  let h1 = 0xdeadbeef ^ str.length;
  let h2 = 0x41c6ce57 ^ str.length;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 'mtl_sha_' + (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

function verifyAdminPassword(candidatePassword) {
  if (!candidatePassword) return false;
  const candidateHash = computeAdminPasswordHash(candidatePassword);
  let storedHash = null;
  try {
    storedHash = localStorage.getItem('mytownlens_admin_pass_hash');
  } catch (e) {}
  if (storedHash) {
    return candidateHash === storedHash;
  }
  return candidateHash === computeAdminPasswordHash(DEFAULT_ADMIN_PASSWORD);
}

function isAdminAuthenticated() {
  try {
    if (typeof sessionStorage !== 'undefined' && sessionStorage.getItem('mytownlens_admin_session') === 'authenticated') {
      return true;
    }
    const rememberUntil = Number(localStorage.getItem('mytownlens_admin_remember_until') || 0);
    if (rememberUntil > Date.now()) {
      return true;
    }
  } catch (e) {}
  return false;
}

function toggleAdminPasswordVisibility(inputId, btnId) {
  const input = document.getElementById(inputId);
  const btn = document.getElementById(btnId);
  if (!input) return;
  const isNowVisible = input.type === 'password';
  input.type = isNowVisible ? 'text' : 'password';
  if (btn) {
    btn.setAttribute('aria-pressed', String(isNowVisible));
    btn.textContent = isNowVisible ? '🙈 Hide password' : '👁️ Show password';
  }
}

function populateAdminTownContextSelect() {
  const select = document.getElementById('admin-active-town-select');
  if (!select) return;
  if (select.children.length === 0) {
    const towns = Object.values(CITY_REGISTRY).sort((a, b) => a.name.localeCompare(b.name));
    select.innerHTML = towns.map(t => `
      <option value="${escapeHtml(t.id)}">${escapeHtml(t.name)} (${escapeHtml(t.countyShort || t.county)})</option>
    `).join('');
  }
  select.value = currentCity || 'clifton';
}

async function handleAdminTownSwitch(townId) {
  if (!townId || !CITY_REGISTRY[townId]) return;
  await switchCity(townId);
  populateAdminTownContextSelect();
  renderAdminLeadsData();
  showToast(`✓ Switched active admin municipality context to ${CITY_REGISTRY[townId].name}`);
}

function initAdminPortalWorkspace() {
  const gate = document.getElementById('admin-auth-gate');
  const workspace = document.getElementById('admin-portal-workspace');
  const sessionBadge = document.getElementById('admin-session-badge');
  const logoutBtn = document.getElementById('btn-admin-header-logout');
  if (!gate || !workspace) return;

  if (isAdminAuthenticated()) {
    gate.style.display = 'none';
    gate.setAttribute('aria-hidden', 'true');
    workspace.style.display = 'block';
    workspace.setAttribute('aria-hidden', 'false');
    if (sessionBadge) sessionBadge.style.display = 'inline-flex';
    if (logoutBtn) logoutBtn.style.display = 'inline-flex';
    populateAdminTownContextSelect();
    renderAdminLeadsData();
    renderAdminSponsorsData();
    renderAdminOutreachData();
    renderAdminRealtorOutreachData();
  } else {
    gate.style.display = 'flex';
    gate.setAttribute('aria-hidden', 'false');
    workspace.style.display = 'none';
    workspace.setAttribute('aria-hidden', 'true');
    if (sessionBadge) sessionBadge.style.display = 'none';
    if (logoutBtn) logoutBtn.style.display = 'none';
  }
}

function handleAdminLoginSubmit(e) {
  if (e && typeof e.preventDefault === 'function') e.preventDefault();
  const passInput = document.getElementById('admin-login-password');
  const rememberBox = document.getElementById('admin-remember-device');
  const errBanner = document.getElementById('admin-login-error-banner');
  const passVal = passInput ? passInput.value : '';

  if (verifyAdminPassword(passVal)) {
    try {
      if (typeof sessionStorage !== 'undefined') {
        sessionStorage.setItem('mytownlens_admin_session', 'authenticated');
      }
      if (rememberBox && rememberBox.checked) {
        localStorage.setItem('mytownlens_admin_remember_until', String(Date.now() + 7 * 24 * 60 * 60 * 1000));
      } else {
        localStorage.removeItem('mytownlens_admin_remember_until');
      }
    } catch (err) {}
    if (errBanner) errBanner.style.display = 'none';
    if (passInput) {
      passInput.setAttribute('aria-invalid', 'false');
      passInput.classList.remove('user-invalid-fallback');
      passInput.value = '';
    }
    initAdminPortalWorkspace();
    showToast('🔓 Signed in to MyTownLens Admin Portal');
    return true;
  } else {
    if (errBanner) errBanner.style.display = 'flex';
    if (passInput) {
      passInput.setAttribute('aria-invalid', 'true');
      passInput.classList.add('user-invalid-fallback');
      passInput.focus();
    }
    return false;
  }
}

function handleAdminLogout() {
  try {
    if (typeof sessionStorage !== 'undefined') {
      sessionStorage.removeItem('mytownlens_admin_session');
    }
    localStorage.removeItem('mytownlens_admin_remember_until');
  } catch (e) {}
  closeLeadDossierPreview();
  initAdminPortalWorkspace();
  showToast('🔒 Signed out and locked Admin Portal');
}

function handleAdminPasswordChange(e) {
  if (e && typeof e.preventDefault === 'function') e.preventDefault();
  const curInput = document.getElementById('admin-current-pass');
  const newInput = document.getElementById('admin-new-pass');
  const msgEl = document.getElementById('admin-password-change-msg');

  const curVal = curInput ? curInput.value : '';
  const newVal = newInput ? newInput.value : '';

  if (!verifyAdminPassword(curVal)) {
    if (msgEl) {
      msgEl.innerHTML = `<span style="color: #dc2626; font-weight: 700;">❌ Current administrator password is incorrect.</span>`;
    }
    return false;
  }
  if (!newVal || newVal.length < 8) {
    if (msgEl) {
      msgEl.innerHTML = `<span style="color: #dc2626; font-weight: 700;">❌ New password must be at least 8 characters long.</span>`;
    }
    return false;
  }

  try {
    localStorage.setItem('mytownlens_admin_pass_hash', computeAdminPasswordHash(newVal));
  } catch (err) {}

  if (curInput) curInput.value = '';
  if (newInput) newInput.value = '';
  if (msgEl) {
    msgEl.innerHTML = `<span style="color: #059669; font-weight: 700;">✓ Administrator password updated and encrypted!</span>`;
  }
  showToast('✓ Administrator password updated');
  return true;
}

function resetAdminPasswordToDefault() {
  try {
    localStorage.removeItem('mytownlens_admin_pass_hash');
  } catch (e) {}
  const msgEl = document.getElementById('admin-password-change-msg');
  if (msgEl) {
    msgEl.innerHTML = `<span style="color: #2563eb; font-weight: 700;">✓ Password reset to default (${DEFAULT_ADMIN_PASSWORD}).</span>`;
  }
  showToast('✓ Admin password reset to default');
}

function exportAllAdminBackupJSON() {
  const payload = {
    exportedAt: new Date().toISOString(),
    platform: 'MyTownLens Administrative Suite',
    version: '2026.11',
    data: {
      attorneyLeads: JSON.parse(localStorage.getItem('mytownlens_attorney_leads') || '[]'),
      realtorLeads: JSON.parse(localStorage.getItem('mytownlens_realtor_leads') || '[]'),
      partnerInquiries: JSON.parse(localStorage.getItem('mytownlens_partner_inquiries') || '[]'),
      sponsors: JSON.parse(localStorage.getItem('mytownlens_sponsors') || '{}'),
      lawFirmCRM: JSON.parse(localStorage.getItem('mytownlens_law_firm_crm') || '[]'),
      realtorBrokerageCRM: JSON.parse(localStorage.getItem('mytownlens_realtor_brokerage_crm') || '[]'),
      webhookUrl: localStorage.getItem('mytownlens_lead_webhook') || '',
      partnerEmail: localStorage.getItem('mytownlens_partner_email') || ''
    }
  };

  const jsonStr = JSON.stringify(payload, null, 2);
  const blob = new Blob([jsonStr], { type: 'application/json;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `mytownlens_admin_backup_${new Date().toISOString().split('T')[0]}.json`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);

  const msgEl = document.getElementById('admin-backup-status-msg');
  if (msgEl) {
    msgEl.innerHTML = `<span style="color: #059669; font-weight: 700;">✓ Full administrative backup downloaded successfully.</span>`;
  }
  showToast('✓ Exported full Admin JSON backup');
  return payload;
}

function importAllAdminBackupJSON(event) {
  const file = event?.target?.files?.[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const parsed = JSON.parse(e.target.result);
      const d = parsed?.data || parsed;
      if (Array.isArray(d.attorneyLeads)) localStorage.setItem('mytownlens_attorney_leads', JSON.stringify(d.attorneyLeads));
      if (Array.isArray(d.realtorLeads)) localStorage.setItem('mytownlens_realtor_leads', JSON.stringify(d.realtorLeads));
      if (Array.isArray(d.partnerInquiries)) localStorage.setItem('mytownlens_partner_inquiries', JSON.stringify(d.partnerInquiries));
      if (d.sponsors && typeof d.sponsors === 'object') localStorage.setItem('mytownlens_sponsors', JSON.stringify(d.sponsors));
      if (Array.isArray(d.lawFirmCRM)) localStorage.setItem('mytownlens_law_firm_crm', JSON.stringify(d.lawFirmCRM));
      if (Array.isArray(d.realtorBrokerageCRM)) localStorage.setItem('mytownlens_realtor_brokerage_crm', JSON.stringify(d.realtorBrokerageCRM));
      if (typeof d.webhookUrl === 'string' && d.webhookUrl) localStorage.setItem('mytownlens_lead_webhook', d.webhookUrl);
      if (typeof d.partnerEmail === 'string' && d.partnerEmail) localStorage.setItem('mytownlens_partner_email', d.partnerEmail);

      renderAdminLeadsData();
      renderAdminSponsorsData();
      renderAdminOutreachData();
      renderAdminRealtorOutreachData();

      const msgEl = document.getElementById('admin-backup-status-msg');
      if (msgEl) {
        msgEl.innerHTML = `<span style="color: #059669; font-weight: 700;">✓ Restored all administrative records from ${escapeHtml(file.name)}!</span>`;
      }
      showToast('✓ Administrative backup restored');
    } catch (err) {
      const msgEl = document.getElementById('admin-backup-status-msg');
      if (msgEl) {
        msgEl.innerHTML = `<span style="color: #dc2626; font-weight: 700;">❌ Failed to parse JSON backup file.</span>`;
      }
    }
  };
  reader.readAsText(file);
}

function openAdminLeadsModal() {
  const modal = document.getElementById('admin-leads-dialog');
  if (!modal) {
    if (typeof window !== 'undefined' && window.location && !window.location.pathname.endsWith('admin.html')) {
      window.location.href = 'admin.html';
    }
    return;
  }
  renderAdminLeadsData();
  renderAdminSponsorsData();
  renderAdminOutreachData();
  renderAdminRealtorOutreachData();
  if (typeof modal.showModal === 'function') {
    modal.showModal();
  } else {
    modal.setAttribute('open', '');
  }
}

function closeAdminLeadsModal() {
  const modal = document.getElementById('admin-leads-dialog');
  if (!modal) return;
  if (typeof modal.close === 'function') {
    modal.close();
  } else {
    modal.removeAttribute('open');
  }
}

function switchAdminTab(tabName) {
  const tabs = ['appeals', 'realtor', 'partners', 'settings', 'sponsors', 'outreach', 'realtor_outreach', 'security'];
  tabs.forEach(t => {
    const btn = document.getElementById(`admin-tab-${t}-btn`);
    const panel = document.getElementById(`admin-panel-${t}`);
    const isSelected = (t === tabName);
    if (btn) {
      btn.setAttribute('aria-selected', String(isSelected));
      if (isSelected) {
        btn.classList.add('active');
        if (typeof btn.scrollIntoView === 'function') {
          try {
            btn.scrollIntoView({ block: 'nearest', inline: 'nearest' });
          } catch (e) {}
        }
      } else {
        btn.classList.remove('active');
      }
    }
    if (panel) {
      panel.style.display = isSelected ? 'block' : 'none';
    }
  });
  if (tabName === 'sponsors') {
    renderAdminSponsorsData();
  } else if (tabName === 'outreach') {
    renderAdminOutreachData();
  } else if (tabName === 'realtor_outreach') {
    renderAdminRealtorOutreachData();
  }
}

function getLeadSavingsAmount(item) {
  if (item?.caseMerits?.potentialAnnualSavings !== undefined) {
    return Number(item.caseMerits.potentialAnnualSavings) || 0;
  }
  const tax = Number(item?.property?.annualTax) || 0;
  return Math.round(tax * 0.15);
}

function renderAdminLeadsData() {
  let appeals = [];
  let realtor = [];
  let partners = [];
  try {
    appeals = JSON.parse(localStorage.getItem('mytownlens_attorney_leads') || '[]');
    realtor = JSON.parse(localStorage.getItem('mytownlens_realtor_leads') || '[]');
    partners = JSON.parse(localStorage.getItem('mytownlens_partner_inquiries') || '[]');
  } catch (e) {
    console.warn('Error reading leads from localStorage:', e);
  }

  // Update KPIs
  const appealCountEl = document.getElementById('admin-kpi-appeal-count');
  const appealSavingsEl = document.getElementById('admin-kpi-appeal-savings');
  const realtorCountEl = document.getElementById('admin-kpi-realtor-count');
  const realtorValEl = document.getElementById('admin-kpi-realtor-val');
  const partnerCountEl = document.getElementById('admin-kpi-partner-count');
  const webhookStatusEl = document.getElementById('admin-kpi-webhook-status');
  const webhookSubEl = document.getElementById('admin-kpi-webhook-sub');

  if (appealCountEl) appealCountEl.textContent = appeals.length;
  if (appealSavingsEl) {
    const totalSavings = appeals.reduce((sum, item) => sum + getLeadSavingsAmount(item), 0);
    appealSavingsEl.textContent = `$${totalSavings.toLocaleString()} Est. Potential Savings`;
  }

  if (realtorCountEl) realtorCountEl.textContent = realtor.length;
  if (realtorValEl) {
    const totalVal = realtor.reduce((sum, item) => sum + (Number(item.property?.estimatedMarketValue) || 450000), 0);
    realtorValEl.textContent = `$${(totalVal / 1000000).toFixed(2)}M Property Volume`;
  }

  if (partnerCountEl) partnerCountEl.textContent = partners.length;

  const currentWebhook = localStorage.getItem('mytownlens_lead_webhook') || '';
  const currentPartnerEmail = localStorage.getItem('mytownlens_partner_email') || '';
  if (webhookStatusEl && webhookSubEl) {
    if (currentWebhook) {
      try {
        const urlObj = new URL(currentWebhook);
        webhookStatusEl.textContent = 'Active ⚡';
        webhookStatusEl.style.color = '#10b981';
        webhookSubEl.textContent = urlObj.hostname;
      } catch (err) {
        webhookStatusEl.textContent = 'Configured';
        webhookSubEl.textContent = 'Webhook saved';
      }
    } else if (currentPartnerEmail) {
      webhookStatusEl.textContent = 'Email Ready';
      webhookStatusEl.style.color = '#2563eb';
      webhookSubEl.textContent = currentPartnerEmail;
    } else {
      webhookStatusEl.textContent = 'Local Only';
      webhookStatusEl.style.color = '#64748b';
      webhookSubEl.textContent = 'Push alerts offline';
    }
  }

  const webhookInput = document.getElementById('admin-webhook-url');
  if (webhookInput && !webhookInput.value) {
    webhookInput.value = currentWebhook;
  }
  const partnerEmailInput = document.getElementById('admin-partner-email');
  if (partnerEmailInput && !partnerEmailInput.value) {
    partnerEmailInput.value = currentPartnerEmail;
  }

  // Render Table 1: Appeals (Golden Dockets)
  const tbodyAppeals = document.getElementById('admin-tbody-appeals');
  if (tbodyAppeals) {
    if (appeals.length === 0) {
      tbodyAppeals.innerHTML = `<tr><td colspan="7" style="text-align: center; padding: 20px; color: #94a3b8;">No homeowner tax appeal leads yet. Submissions from the Tax Appeal Analyzer will appear here, or click <strong>⚡ Generate Sample Lead</strong> above to create a real MOD-IV case docket.</td></tr>`;
    } else {
      tbodyAppeals.innerHTML = appeals.map(a => {
        const dateStr = a.submittedAt ? new Date(a.submittedAt).toLocaleDateString() + ' ' + new Date(a.submittedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—';
        const contact = a.contact || {};
        const prop = a.property || {};
        const merits = a.caseMerits || {};
        const compsCount = Array.isArray(a.comparables) ? a.comparables.length : 0;
        const savings = getLeadSavingsAmount(a);
        const overAssess = merits.indicatedOverAssessment !== undefined ? merits.indicatedOverAssessment : Math.round((Number(prop.assessedTotal) || 0) * 0.12);
        const overPct = merits.overAssessmentPct !== undefined ? merits.overAssessmentPct : 12.0;

        return `
          <tr>
            <td style="font-size: 0.75rem; color: #64748b; white-space: nowrap;">${dateStr}</td>
            <td>
              <strong>${escapeHtml(contact.name || '—')}</strong>
              <div style="font-size: 0.7rem; color: #059669; font-weight: 700;">${contact.isLegalOwner !== false ? '✓ Owner Verified' : 'Taxpayer'}</div>
            </td>
            <td>
              <div>${escapeHtml(contact.phone || '—')}</div>
              <div style="font-size: 0.74rem; color: #64748b;">${escapeHtml(contact.email || '—')}</div>
              <div style="font-size: 0.7rem; color: #94a3b8;">Pref: ${escapeHtml(contact.preferredContact || 'phone')}</div>
            </td>
            <td>
              <div><strong>${escapeHtml(prop.address || '—')}</strong></div>
              <div style="font-size: 0.72rem; color: #64748b;">B: ${escapeHtml(prop.block)} / L: ${escapeHtml(prop.lot)} &bull; Assess: $${Number(prop.assessedTotal || 0).toLocaleString()}</div>
            </td>
            <td>
              <div><strong>${escapeHtml(prop.municipality || '—')}</strong></div>
              <div style="font-size: 0.72rem; color: #64748b;">${escapeHtml(prop.county || '')}</div>
            </td>
            <td>
              <div style="color: #059669; font-weight: 800; font-size: 0.86rem;">$${savings.toLocaleString()} / yr</div>
              <div style="font-size: 0.72rem; color: #b91c1c; font-weight: 600;">+$${Number(overAssess).toLocaleString()} (+${overPct}%)</div>
              <div style="font-size: 0.7rem; color: #2563eb; font-weight: 700;">${compsCount > 0 ? `✓ ${compsCount} Comps Attached` : 'MOD-IV Roll'}</div>
            </td>
            <td style="white-space: nowrap;">
              <div style="display: flex; gap: 4px; flex-wrap: wrap;">
                <button type="button" class="btn-sponsor-table-edit" onclick="openLeadDossierPreview('appeals', '${escapeHtml(a.id)}')" title="Inspect full formatted Case Dossier">📄 Dossier</button>
                <button type="button" class="btn-sponsor-table-edit" onclick="copyLeadDossierById('appeals', '${escapeHtml(a.id)}')" title="Copy full Case Dossier to clipboard">📋 Copy</button>
                <button type="button" class="btn-sponsor-table-edit" style="background:#ecfdf5; border-color:#a7f3d0; color:#047857;" onclick="emailLeadDossierById('appeals', '${escapeHtml(a.id)}')" title="Email Case Dossier to Partner Attorney">📧 Send</button>
              </div>
            </td>
          </tr>
        `;
      }).join('');
    }
  }

  // Render Table 2: Realtor
  const tbodyRealtor = document.getElementById('admin-tbody-realtor');
  if (tbodyRealtor) {
    if (realtor.length === 0) {
      tbodyRealtor.innerHTML = `<tr><td colspan="7" style="text-align: center; padding: 20px; color: #94a3b8;">No homeowner CMA valuation leads yet. Requests from the Free Realtor Valuation button will appear here, or click <strong>⚡ Generate Sample CMA Lead</strong> above.</td></tr>`;
    } else {
      tbodyRealtor.innerHTML = realtor.map(r => {
        const dateStr = r.submittedAt ? new Date(r.submittedAt).toLocaleDateString() + ' ' + new Date(r.submittedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—';
        const contact = r.contact || {};
        const prop = r.property || {};
        return `
          <tr>
            <td style="font-size: 0.76rem; color: #64748b; white-space: nowrap;">${dateStr}</td>
            <td><strong>${escapeHtml(contact.name || '—')}</strong></td>
            <td><div>${escapeHtml(contact.phone || '—')}</div><div style="font-size: 0.75rem; color: #64748b;">${escapeHtml(contact.email || '—')}</div></td>
            <td><div><strong>${escapeHtml(prop.address || '—')}</strong></div><div style="font-size: 0.72rem; color: #94a3b8;">B: ${escapeHtml(prop.block)} / L: ${escapeHtml(prop.lot)}</div></td>
            <td>${escapeHtml(prop.municipality || '—')}</td>
            <td>
              <div style="font-weight: 700; color: #0284c7;">$${(Number(prop.estimatedMarketValue) || 0).toLocaleString()}</div>
              <div style="font-size: 0.72rem; color: #475569;">${escapeHtml((contact.timeline || 'curious').replace(/_/g, ' '))}</div>
            </td>
            <td style="white-space: nowrap;">
              <div style="display: flex; gap: 4px; flex-wrap: wrap;">
                <button type="button" class="btn-sponsor-table-edit" onclick="openLeadDossierPreview('realtor', '${escapeHtml(r.id)}')">📄 Dossier</button>
                <button type="button" class="btn-sponsor-table-edit" onclick="copyLeadDossierById('realtor', '${escapeHtml(r.id)}')">📋 Copy</button>
                <button type="button" class="btn-sponsor-table-edit" style="background:#ecfdf5; border-color:#a7f3d0; color:#047857;" onclick="emailLeadDossierById('realtor', '${escapeHtml(r.id)}')">📧 Send</button>
              </div>
            </td>
          </tr>
        `;
      }).join('');
    }
  }

  // Render Table 3: Partners
  const tbodyPartners = document.getElementById('admin-tbody-partners');
  if (tbodyPartners) {
    if (partners.length === 0) {
      tbodyPartners.innerHTML = `<tr><td colspan="7" style="text-align: center; padding: 20px; color: #94a3b8;">No municipal sponsorship inquiries yet. Submissions from the Partner with MyTownLens banner will appear here.</td></tr>`;
    } else {
      tbodyPartners.innerHTML = partners.map(p => {
        const dateStr = p.submittedAt ? new Date(p.submittedAt).toLocaleDateString() + ' ' + new Date(p.submittedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—';
        return `
          <tr>
            <td style="font-size: 0.76rem; color: #64748b; white-space: nowrap;">${dateStr}</td>
            <td><strong>${escapeHtml(p.name || '—')}</strong></td>
            <td>${escapeHtml(p.firm || '—')}</td>
            <td><span style="display: inline-block; padding: 2px 6px; font-size: 0.72rem; border-radius: 4px; background: #e0f2fe; color: #0369a1; font-weight: 700;">${escapeHtml(p.role || '—')}</span></td>
            <td>${escapeHtml(p.towns || '—')}</td>
            <td><div>${escapeHtml(p.phone || '—')}</div><div style="font-size: 0.75rem; color: #64748b;">${escapeHtml(p.email || '—')}</div></td>
            <td style="font-size: 0.76rem; color: #475569; max-width: 200px;">${escapeHtml(p.message || '')}</td>
          </tr>
        `;
      }).join('');
    }
  }
}

function findLeadRecordById(type, leadId) {
  const storageKey = type === 'appeals' ? 'mytownlens_attorney_leads' : 'mytownlens_realtor_leads';
  try {
    const list = JSON.parse(localStorage.getItem(storageKey) || '[]');
    return list.find(item => item.id === leadId) || null;
  } catch (e) {
    return null;
  }
}

function openLeadDossierPreview(type, leadId) {
  const record = findLeadRecordById(type, leadId);
  if (!record) {
    showToast('⚠️ Lead record not found');
    return;
  }
  const inspector = document.getElementById('admin-dossier-inspector');
  const titleEl = document.getElementById('admin-dossier-title');
  const subEl = document.getElementById('admin-dossier-subtitle');
  const preEl = document.getElementById('admin-dossier-pre');

  const dossierText = record.formattedDossier || buildFormattedLeadDossier(type, record);
  activeInspectedDossier = { type, record, text: dossierText };

  if (titleEl) {
    titleEl.textContent = type === 'appeals'
      ? `📄 Tax Appeal Case Dossier: ${record.property?.address || ''} (${record.property?.municipality || ''})`
      : `📄 Realtor CMA Valuation Dossier: ${record.property?.address || ''} (${record.property?.municipality || ''})`;
  }
  if (subEl) {
    subEl.textContent = `Applicant: ${record.contact?.name || ''} • ${record.contact?.phone || ''} • ${record.contact?.email || ''}`;
  }
  if (preEl) {
    preEl.textContent = dossierText;
  }
  if (inspector) {
    inspector.style.display = 'block';
    if (typeof inspector.scrollIntoView === 'function') {
      inspector.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }
}

function closeLeadDossierPreview() {
  const inspector = document.getElementById('admin-dossier-inspector');
  if (inspector) inspector.style.display = 'none';
}

function copyActiveInspectedDossier() {
  if (!activeInspectedDossier || !activeInspectedDossier.text) return;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(activeInspectedDossier.text).then(() => {
      showToast('✓ Full Case Dossier copied to clipboard!');
    }).catch(() => {
      showToast('✓ Copied to clipboard');
    });
  }
}

function emailActiveInspectedDossier() {
  if (!activeInspectedDossier || !activeInspectedDossier.record) return;
  emailLeadDossierById(activeInspectedDossier.type, activeInspectedDossier.record.id);
}

function copyLeadDossierById(type, leadId) {
  const record = findLeadRecordById(type, leadId);
  if (!record) return;
  const text = record.formattedDossier || buildFormattedLeadDossier(type, record);
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      showToast('✓ Pre-qualified lead dossier copied to clipboard!');
    }).catch(() => {
      showToast('✓ Dossier copied');
    });
  }
}

function emailLeadDossierById(type, leadId) {
  const record = findLeadRecordById(type, leadId);
  if (!record) return;
  const partnerEmail = localStorage.getItem('mytownlens_partner_email') || '';
  const p = record.property || {};
  const text = record.formattedDossier || buildFormattedLeadDossier(type, record);
  const subject = type === 'appeals'
    ? `Pre-Qualified NJ Tax Appeal Lead: ${p.address || ''}, ${p.municipality || ''} (Est. Savings: $${getLeadSavingsAmount(record).toLocaleString()}/yr)`
    : `Homeowner CMA Valuation Lead: ${p.address || ''}, ${p.municipality || ''} ($${Number(p.estimatedMarketValue || 450000).toLocaleString()})`;

  const mailtoUrl = `mailto:${encodeURIComponent(partnerEmail)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(text)}`;
  if (typeof window !== 'undefined') {
    window.location.href = mailtoUrl;
  }
  showToast('📧 Opened email client with formatted Case Dossier');
}

function generateSampleQualifiedLead(type = 'appeals') {
  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;
  const props = propertyAssessmentsData?.properties || [];
  const rate = parseFloat(meta.certifiedTaxRate) || meta.rateNum || 2.5;
  const eqRatio = parseFloat(meta.equalizationRatio) || 100.0;

  // Pick a real high-assessment parcel from the active town's MOD-IV roll
  let subject = props.find(p => p.assessedTotal > (propertyAssessmentsData?.summaryStats?.averageAssessed || 200000) * 1.18) || props[0] || {
    id: `${currentCity}-sample-1`,
    address: '142 OAK RIDGE RD',
    block: '18.02',
    lot: '14',
    propertyType: 'Single Family',
    bldgDesc: '2S-F-C',
    yearBuilt: 1968,
    assessedLand: 145000,
    assessedBuilding: 215000,
    assessedTotal: 360000,
    annualTax: Math.round(3600 * rate * 100) / 100,
    estimatedMarketValue: 685000
  };

  if (type === 'realtor') {
    const sampleRealtor = {
      id: 'realtor_sample_' + Date.now(),
      submittedAt: new Date().toISOString(),
      property: {
        address: subject.address,
        block: subject.block,
        lot: subject.lot,
        estimatedMarketValue: subject.estimatedMarketValue || 625000,
        municipality: meta.name,
        county: meta.county
      },
      contact: {
        name: 'David & Sarah Miller [Sample Lead]',
        phone: '(973) 555-0184',
        email: 'dmiller.homeowner@example.com',
        timeline: '1-3_months',
        notes: 'Updated kitchen (2023), finished basement, considering listing before summer market.'
      }
    };
    sampleRealtor.formattedDossier = buildFormattedLeadDossier('realtor', sampleRealtor);
    try {
      const existing = JSON.parse(localStorage.getItem('mytownlens_realtor_leads') || '[]');
      existing.unshift(sampleRealtor);
      localStorage.setItem('mytownlens_realtor_leads', JSON.stringify(existing));
    } catch (e) {}
    renderAdminLeadsData();
    openLeadDossierPreview('realtor', sampleRealtor.id);
    showToast(`✓ Generated sample Realtor CMA lead for ${subject.address} (${meta.name})`);
    return sampleRealtor;
  }

  // Find 4 lower-assessed street/neighborhood comparables from the roll
  const compsPool = props.filter(p => p.id !== subject.id && p.assessedTotal < subject.assessedTotal * 0.92).slice(0, 4);
  const compMedian = compsPool.length > 0
    ? compsPool[Math.floor(compsPool.length / 2)].assessedTotal
    : Math.round(subject.assessedTotal * 0.84);
  const diff = Math.max(15000, subject.assessedTotal - compMedian);
  const diffPct = +((diff / Math.max(1, compMedian)) * 100).toFixed(1);
  const potentialSavings = Math.max(450, Math.round((diff / 100) * rate));

  const sampleAppeal = {
    id: 'lead_sample_' + Date.now(),
    submittedAt: new Date().toISOString(),
    property: {
      id: subject.id || '',
      address: subject.address,
      block: subject.block,
      lot: subject.lot,
      pamsPin: subject.pamsPin || `${meta.districtCode || '1602'}_${subject.block}_${subject.lot}`,
      propertyClass: '2',
      propertyType: subject.propertyType || 'Single Family',
      bldgDesc: subject.bldgDesc || 'Class 2 Residential',
      yearBuilt: subject.yearBuilt || 1965,
      lotSize: subject.lotSize || '75X125',
      assessedLand: subject.assessedLand || Math.round(subject.assessedTotal * 0.4),
      assessedBuilding: subject.assessedBuilding || Math.round(subject.assessedTotal * 0.6),
      assessedTotal: subject.assessedTotal,
      certifiedTaxRate: meta.certifiedTaxRate || `${rate}%`,
      annualTax: subject.annualTax,
      estimatedMarketValue: subject.estimatedMarketValue || 640000,
      municipality: meta.name,
      county: meta.county,
      districtCode: meta.districtCode || ''
    },
    caseMerits: {
      equalizationRatio: eqRatio,
      corridorLower: +(eqRatio * 0.85).toFixed(1),
      corridorUpper: +(eqRatio * 1.15).toFixed(1),
      streetMedianAssessment: compMedian,
      indicatedOverAssessment: diff,
      overAssessmentPct: diffPct,
      potentialAnnualSavings: potentialSavings,
      interiorSpecs: { bedrooms: '3', bathrooms: '2', sqft: '1,850', condition: 'dated' }
    },
    comparables: compsPool.map(c => ({
      address: c.address,
      block: c.block,
      lot: c.lot,
      propertyType: c.propertyType || 'Single Family',
      yearBuilt: c.yearBuilt || 1964,
      assessedTotal: c.assessedTotal,
      annualTax: c.annualTax,
      salePrice: c.salePrice || 0,
      deedDate: c.deedDate || ''
    })),
    contact: {
      name: 'Michael &Elena Rostova [Sample Dossier]',
      phone: '(973) 555-0192',
      email: 'mrostova.taxpayer@example.com',
      preferredContact: 'phone',
      isLegalOwner: true,
      notes: 'Original 1970s kitchen and baths, water seepage in unfinished basement, assessment is $' + diff.toLocaleString() + ' above neighbors on same block.'
    }
  };

  sampleAppeal.formattedDossier = buildFormattedLeadDossier('appeals', sampleAppeal);

  try {
    const existing = JSON.parse(localStorage.getItem('mytownlens_attorney_leads') || '[]');
    existing.unshift(sampleAppeal);
    localStorage.setItem('mytownlens_attorney_leads', JSON.stringify(existing));
  } catch (e) {}

  renderAdminLeadsData();
  openLeadDossierPreview('appeals', sampleAppeal.id);
  showToast(`✓ Generated sample Golden Lead Dossier for ${subject.address} (${meta.name})`);
  return sampleAppeal;
}

function copyBuyerPitchScript(buyerType = 'attorney') {
  const meta = CITY_REGISTRY[currentCity] || CITY_REGISTRY.clifton;
  const totalParcels = propertyAssessmentsData?.summaryStats?.totalProperties || 21300;
  const avgTax = propertyAssessmentsData?.summaryStats?.averageTax || 11782;

  const pitch = buyerType === 'attorney'
    ? [
      `Subject: 3 Free Pre-Qualified ${meta.name} (${meta.countyShort}) Property Tax Appeal Case Dockets`,
      '',
      'Hi [Managing Partner / Attorney Name],',
      '',
      `I run MyTownLens (mytownlens.com), a public property tax and MOD-IV assessment intelligence platform covering all 47 municipalities across Passaic, Bergen, Essex, and Morris counties (150,016 certified Class 2 residential parcels, including ${totalParcels.toLocaleString()} homes in ${meta.name} where the average tax bill is $${Math.round(avgTax).toLocaleString()}/yr).`,
      '',
      `Homeowners in ${meta.name} and surrounding ${meta.countyShort} towns are actively using our Chapter 123 Tax Appeal Analyzer to check if their property is over-assessed before the April 1 filing deadline.`,
      '',
      'When a homeowner requests a professional review, our system packages a complete "Golden Lead Case Dossier" containing:',
      '  1. Verified Homeowner Contact Info & Legal Representation Consent',
      '  2. Subject Parcel Block, Lot, PAMS PIN, Land/Building Assessment & 2026 Tax Bill',
      '  3. Chapter 123 Common Level Ratio Variance & Indicated Annual Tax Savings ($/yr)',
      '  4. 3 to 5 Verified MOD-IV Street Comparable Sales with Deed Dates & Ratios',
      '',
      `I would like to send your intake desk 3 pre-qualified ${meta.countyShort} homeowner case dockets free of charge this week so you can see the dossier quality firsthand. If they convert into contingency filings for your firm, we can discuss a simple per-lead arrangement ($75–$125/lead) or exclusive town sponsorship for ${meta.name}.`,
      '',
      'Where is the best email address to forward your 3 complimentary case dockets?',
      '',
      'Best regards,',
      '[Your Name]',
      'Founder, MyTownLens (mytownlens.com)'
    ].join('\n')
    : [
      `Subject: Exclusive ${meta.name} Homeowner CMA & Seller Valuation Leads (MyTownLens)`,
      '',
      'Hi [Broker / Team Leader Name],',
      '',
      `I run MyTownLens (mytownlens.com), a local property tax and housing intelligence platform monitoring ${totalParcels.toLocaleString()} residential properties in ${meta.name} and 150,016 homes across 47 North Jersey towns.`,
      '',
      `Homeowners looking up their ${meta.name} tax assessments and 2027 revaluation projections frequently request an off-market Comparative Market Analysis (CMA) from a local neighborhood specialist before listing or refinancing.`,
      '',
      `I'd love to send you our next 3 ${meta.name} homeowner valuation requests free of charge so you can evaluate the lead intent. We also offer exclusive single-agent sponsorship for ${meta.name}.`,
      '',
      'What is the best email or cell number to route your 3 complimentary homeowner CMA leads?',
      '',
      'Best regards,',
      '[Your Name]',
      'Founder, MyTownLens (mytownlens.com)'
    ].join('\n');

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(pitch).then(() => {
      showToast(`✓ Copied ${buyerType === 'attorney' ? 'Tax Appeal Attorney' : 'Realtor'} cold-pitch email script!`);
    }).catch(() => {
      showToast('✓ Pitch script copied');
    });
  }
  return pitch;
}

function exportLeadsCSV(type) {
  let rows = [];
  let filename = '';

  const escapeCSV = (val) => {
    if (val === null || val === undefined) return '""';
    const s = String(val).replace(/"/g, '""');
    return `"${s}"`;
  };

  if (type === 'appeals') {
    filename = `mytownlens_attorney_leads_${Date.now()}.csv`;
    const data = JSON.parse(localStorage.getItem('mytownlens_attorney_leads') || '[]');
    if (data.length === 0) {
      showToast('⚠️ No attorney leads to export');
      return;
    }
    rows.push([
      'Lead ID', 'Timestamp', 'Homeowner Name', 'Phone', 'Email', 'Preferred Contact', 'Legal Owner Verified',
      'Address', 'Block', 'Lot', 'PAMS PIN', 'Municipality', 'County', 'Property Type', 'Year Built',
      'Assessed Land', 'Assessed Building', 'Current Total Assessment', 'Certified Tax Rate', 'Annual Tax',
      'Street Comps Median', 'Indicated Over-Assessment ($)', 'Over-Assessment (%)', 'Est Annual Tax Savings ($/yr)',
      'Ch 123 Ratio (%)', 'Attached MOD-IV Comps', 'Homeowner Notes'
    ].map(escapeCSV).join(','));

    data.forEach(item => {
      const p = item.property || {};
      const c = item.contact || {};
      const m = item.caseMerits || {};
      const comps = Array.isArray(item.comparables) ? item.comparables : [];
      const savings = getLeadSavingsAmount(item);
      const overAssess = m.indicatedOverAssessment !== undefined ? m.indicatedOverAssessment : Math.round((Number(p.assessedTotal) || 0) * 0.12);
      const overPct = m.overAssessmentPct !== undefined ? m.overAssessmentPct : 12.0;
      const compsSummary = comps.map(comp => `${comp.address} (B:${comp.block} L:${comp.lot} $${comp.assessedTotal})`).join(' | ');

      rows.push([
        item.id || '',
        item.submittedAt || '',
        c.name || '',
        c.phone || '',
        c.email || '',
        c.preferredContact || '',
        c.isLegalOwner !== false ? 'Yes' : 'No',
        p.address || '',
        p.block || '',
        p.lot || '',
        p.pamsPin || '',
        p.municipality || '',
        p.county || '',
        p.propertyType || 'Single Family',
        p.yearBuilt || '',
        p.assessedLand || 0,
        p.assessedBuilding || 0,
        p.assessedTotal || 0,
        p.certifiedTaxRate || '',
        p.annualTax || 0,
        m.streetMedianAssessment || p.assessedTotal || 0,
        overAssess,
        overPct,
        savings,
        m.equalizationRatio || '',
        compsSummary,
        c.notes || ''
      ].map(escapeCSV).join(','));
    });
  } else if (type === 'realtor') {
    filename = `mytownlens_realtor_cma_leads_${Date.now()}.csv`;
    const data = JSON.parse(localStorage.getItem('mytownlens_realtor_leads') || '[]');
    if (data.length === 0) {
      showToast('⚠️ No Realtor valuation leads to export');
      return;
    }
    rows.push(['Timestamp', 'Homeowner Name', 'Phone', 'Email', 'Timeline', 'Address', 'Block', 'Lot', 'Municipality', 'County', 'Estimated Market Value', 'Notes'].map(escapeCSV).join(','));
    data.forEach(item => {
      const p = item.property || {};
      const c = item.contact || {};
      rows.push([
        item.submittedAt || '',
        c.name || '',
        c.phone || '',
        c.email || '',
        c.timeline || '',
        p.address || '',
        p.block || '',
        p.lot || '',
        p.municipality || '',
        p.county || '',
        p.estimatedMarketValue || 0,
        c.notes || ''
      ].map(escapeCSV).join(','));
    });
  } else if (type === 'partners') {
    filename = `mytownlens_sponsorship_inquiries_${Date.now()}.csv`;
    const data = JSON.parse(localStorage.getItem('mytownlens_partner_inquiries') || '[]');
    if (data.length === 0) {
      showToast('⚠️ No sponsorship inquiries to export');
      return;
    }
    rows.push(['Timestamp', 'Professional Name', 'Firm / Agency', 'Role', 'Target Municipalities', 'Email', 'Phone', 'Message'].map(escapeCSV).join(','));
    data.forEach(p => {
      rows.push([
        p.submittedAt || '',
        p.name || '',
        p.firm || '',
        p.role || '',
        p.towns || '',
        p.email || '',
        p.phone || '',
        p.message || ''
      ].map(escapeCSV).join(','));
    });
  }

  const csvContent = 'data:text/csv;charset=utf-8,' + encodeURIComponent(rows.join('\n'));
  const link = document.createElement('a');
  link.setAttribute('href', csvContent);
  link.setAttribute('download', filename);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  showToast(`✓ Exported ${rows.length - 1} records to ${filename}`);
}

function clearLeadsData(type) {
  const label = type === 'appeals' ? 'Attorney tax appeal leads' : type === 'realtor' ? 'Realtor valuation leads' : 'Sponsorship inquiries';
  if (!confirm(`Are you sure you want to permanently clear all ${label}? This cannot be undone.`)) return;

  if (type === 'appeals') localStorage.removeItem('mytownlens_attorney_leads');
  else if (type === 'realtor') localStorage.removeItem('mytownlens_realtor_leads');
  else if (type === 'partners') localStorage.removeItem('mytownlens_partner_inquiries');

  closeLeadDossierPreview();
  renderAdminLeadsData();
  showToast(`Cleared ${label}`);
}

function saveAdminWebhook() {
  const input = document.getElementById('admin-webhook-url');
  const emailInput = document.getElementById('admin-partner-email');
  const msgEl = document.getElementById('admin-webhook-status-msg');
  if (!input) return;
  const val = input.value.trim();
  const emailVal = emailInput ? emailInput.value.trim() : '';

  if (val && !val.startsWith('http')) {
    if (msgEl) {
      msgEl.innerHTML = `<span style="color: #ef4444;">⚠️ Please enter a valid Webhook URL beginning with https://</span>`;
    }
    return;
  }

  if (emailVal) {
    localStorage.setItem('mytownlens_partner_email', emailVal);
  } else {
    localStorage.removeItem('mytownlens_partner_email');
  }

  if (val) {
    localStorage.setItem('mytownlens_lead_webhook', val);
    if (msgEl) {
      msgEl.innerHTML = `<span style="color: #10b981;">✓ Delivery settings saved! All future leads will automatically POST their full Golden Dossier to your webhook${emailVal ? ` and route to ${escapeHtml(emailVal)}` : ''}.</span>`;
    }
    showToast('✓ Lead Delivery Settings Saved');
  } else {
    localStorage.removeItem('mytownlens_lead_webhook');
    if (msgEl) {
      msgEl.innerHTML = `<span style="color: #059669;">✓ Settings updated.${emailVal ? ` Partner dispatch email set to ${escapeHtml(emailVal)}.` : ' Leads stored in browser console.'}</span>`;
    }
    showToast('✓ Delivery settings updated');
  }
  renderAdminLeadsData();
}

function testAdminWebhook() {
  const input = document.getElementById('admin-webhook-url');
  const msgEl = document.getElementById('admin-webhook-status-msg');
  const val = input ? input.value.trim() : localStorage.getItem('mytownlens_lead_webhook');

  if (!val || !val.startsWith('http')) {
    if (msgEl) msgEl.innerHTML = `<span style="color: #ef4444;">⚠️ Save a valid webhook URL first to send a test ping.</span>`;
    return;
  }

  if (msgEl) msgEl.innerHTML = `<span style="color: #3b82f6;">Sending test Golden Lead Dossier ping to ${escapeHtml(val)}...</span>`;

  fetch(val, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      name: 'MyTownLens Admin Test',
      email: 'test@mytownlens.com',
      subject: '[MyTownLens] 🧪 Test Webhook Ping Received Successfully',
      message: 'Hello from MyTownLens (mytownlens.com)! Your delivery webhook is working and ready to receive real-time pre-qualified homeowner tax appeal dockets and Realtor CMA leads.',
      source: 'MyTownLens Platform (mytownlens.com)',
      leadType: 'test_ping',
      timestamp: new Date().toISOString(),
      text: '🚀 *MyTownLens Webhook Test!* Your delivery endpoint is operational and ready to receive pre-qualified homeowner leads.'
    }),
    mode: 'cors'
  }).then(resp => {
    if (msgEl) {
      msgEl.innerHTML = `<span style="color: #10b981;">✓ Test ping sent! HTTP Status: ${resp.status}</span>`;
    }
    showToast('✓ Test ping dispatched');
  }).catch(err => {
    if (msgEl) {
      msgEl.innerHTML = `<span style="color: #f59e0b;">⚠️ Ping sent (Note: Browser CORS may restrict reading response, but server likely received payload). Detail: ${escapeHtml(err.message)}</span>`;
    }
  });
}

function copyWidgetSnippet() {
  const codeEl = document.getElementById('admin-widget-code');
  const msgEl = document.getElementById('admin-widget-status-msg');
  if (!codeEl) return;
  const snippet = codeEl.textContent.trim();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(snippet);
  }
  if (msgEl) {
    msgEl.innerHTML = `<span style="color: #10b981; font-weight: 700;">✓ 1-Line Embed Snippet copied to clipboard! Ready to paste into WordPress, Webflow, Squarespace, or partner site.</span>`;
  }
  showToast('✓ Embed snippet copied to clipboard');
}

function previewWidgetInNewTab() {
  if (typeof window !== 'undefined' && window.open) {
    window.open('index.html?embed=true', '_blank');
  }
}

// ==========================================================================
// MONETIZATION FEATURE 5: ⭐ Municipal Sponsor Management & Roster Engine
// ==========================================================================
function populateSponsorTownDropdown() {
  const select = document.getElementById('sponsor-assign-town');
  if (!select || select.children.length > 0) return;

  const towns = Object.values(CITY_REGISTRY).sort((a, b) => a.name.localeCompare(b.name));
  select.innerHTML = towns.map(t => `
    <option value="${escapeHtml(t.id)}">${escapeHtml(t.name)} (${escapeHtml(t.countyShort || t.county)})</option>
  `).join('');
}

function renderAdminSponsorsData() {
  populateSponsorTownDropdown();

  let sponsors = {};
  try {
    sponsors = JSON.parse(localStorage.getItem('mytownlens_sponsors') || '{}');
  } catch (e) {
    sponsors = {};
  }

  const towns = Object.values(CITY_REGISTRY).sort((a, b) => a.name.localeCompare(b.name));
  const tbody = document.getElementById('admin-tbody-sponsors');

  let activeCount = 0;
  let totalMRR = 0;

  if (tbody) {
    tbody.innerHTML = towns.map(t => {
      const sp = sponsors[t.id];
      const isClaimed = Boolean(sp && sp.name);
      if (isClaimed) {
        activeCount++;
        const numRate = parseFloat(String(sp.rate || '').replace(/[^0-9.]/g, '')) || 0;
        totalMRR += numRate;
      }

      const statusBadge = isClaimed
        ? `<span style="display: inline-block; padding: 2px 7px; font-size: 0.72rem; border-radius: 999px; background: #dcfce7; color: #15803d; font-weight: 700;">● Active</span>`
        : `<span style="display: inline-block; padding: 2px 7px; font-size: 0.72rem; border-radius: 999px; background: #f1f5f9; color: #64748b; font-weight: 700;">Available</span>`;

      const firmDisplay = isClaimed
        ? `<strong>${escapeHtml(sp.name)}</strong>`
        : `<span style="color: #94a3b8; font-style: italic;">— Unclaimed —</span>`;

      const roleDisplay = isClaimed ? escapeHtml(sp.role || 'Partner') : '—';
      const contactDisplay = isClaimed
        ? `<div>${escapeHtml(sp.phone || '—')}</div>${sp.url ? `<a href="${escapeHtml(sp.url)}" target="_blank" rel="noopener" style="font-size: 0.74rem; color: #2563eb;">Link ↗</a>` : ''}`
        : '—';

      const rateDisplay = isClaimed ? (sp.rate || '$250 / mo') : '—';

      const actions = isClaimed
        ? `<div style="display: flex; gap: 4px;">
            <button type="button" class="btn-sponsor-table-edit" onclick="editTownSponsor('${escapeHtml(t.id)}')">Edit</button>
            <button type="button" class="btn-sponsor-table-clear" onclick="removeTownSponsor('${escapeHtml(t.id)}')">Clear</button>
           </div>`
        : `<button type="button" class="btn-sponsor-table-edit" onclick="editTownSponsor('${escapeHtml(t.id)}')">Assign</button>`;

      return `
        <tr>
          <td><strong>${escapeHtml(t.name)}</strong></td>
          <td style="font-size: 0.78rem; color: #64748b;">${escapeHtml(t.countyShort || t.county)}</td>
          <td>${statusBadge}</td>
          <td>${firmDisplay}</td>
          <td style="font-size: 0.78rem; color: #334155;">${roleDisplay}</td>
          <td style="font-size: 0.78rem;">${contactDisplay}</td>
          <td style="font-size: 0.78rem; font-weight: 700; color: #0f172a;">${escapeHtml(rateDisplay)}</td>
          <td>${actions}</td>
        </tr>
      `;
    }).join('');
  }

  // Update Counters
  const countEl = document.getElementById('admin-sponsor-count-active');
  const mrrEl = document.getElementById('admin-sponsor-mrr-total');
  if (countEl) countEl.textContent = activeCount;
  if (mrrEl) mrrEl.textContent = `$${totalMRR.toLocaleString()}`;

  // Update Partner KPI sub text
  const partnerSubEl = document.getElementById('admin-kpi-partner-sub');
  if (partnerSubEl) {
    partnerSubEl.textContent = `${activeCount} / 47 Active • $${totalMRR.toLocaleString()} MRR`;
  }
}

function handleSaveTownSponsor(e) {
  e.preventDefault();
  const townId = document.getElementById('sponsor-assign-town')?.value;
  const name = document.getElementById('sponsor-assign-name')?.value?.trim();
  const role = document.getElementById('sponsor-assign-role')?.value;
  const phone = document.getElementById('sponsor-assign-phone')?.value?.trim();
  const url = document.getElementById('sponsor-assign-url')?.value?.trim();
  const rate = document.getElementById('sponsor-assign-rate')?.value?.trim() || '$250 / mo';

  if (!townId || !name || !phone) {
    showToast('⚠️ Please fill in all required fields (Town, Name, Phone)');
    return;
  }

  let sponsors = {};
  try {
    sponsors = JSON.parse(localStorage.getItem('mytownlens_sponsors') || '{}');
  } catch (err) {
    sponsors = {};
  }

  sponsors[townId] = {
    townId,
    name,
    role,
    phone,
    url,
    rate,
    assignedAt: new Date().toISOString()
  };

  try {
    localStorage.setItem('mytownlens_sponsors', JSON.stringify(sponsors));
  } catch (err) {
    console.warn('LocalStorage sponsor save error:', err);
  }

  const meta = CITY_REGISTRY[townId] || CITY_REGISTRY.clifton;
  renderAdminSponsorsData();
  renderHeaderSponsorBadge(currentCity);
  resetSponsorForm();
  showToast(`✓ Assigned exclusive sponsor for ${meta.name}`);
}

function editTownSponsor(townId) {
  const select = document.getElementById('sponsor-assign-town');
  const nameInput = document.getElementById('sponsor-assign-name');
  const roleSelect = document.getElementById('sponsor-assign-role');
  const phoneInput = document.getElementById('sponsor-assign-phone');
  const urlInput = document.getElementById('sponsor-assign-url');
  const rateInput = document.getElementById('sponsor-assign-rate');

  populateSponsorTownDropdown();
  if (select) select.value = townId;

  let sponsors = {};
  try {
    sponsors = JSON.parse(localStorage.getItem('mytownlens_sponsors') || '{}');
  } catch (e) {}

  const sp = sponsors[townId];
  if (sp) {
    if (nameInput) nameInput.value = sp.name || '';
    if (roleSelect && sp.role) roleSelect.value = sp.role;
    if (phoneInput) phoneInput.value = sp.phone || '';
    if (urlInput) urlInput.value = sp.url || '';
    if (rateInput) rateInput.value = sp.rate || '$250 / mo';
  } else {
    resetSponsorForm();
    if (select) select.value = townId;
  }

  if (nameInput) {
    nameInput.focus();
    nameInput.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}

function removeTownSponsor(townId) {
  const meta = CITY_REGISTRY[townId] || CITY_REGISTRY.clifton;
  if (!confirm(`Are you sure you want to remove the exclusive sponsor for ${meta.name}?`)) return;

  let sponsors = {};
  try {
    sponsors = JSON.parse(localStorage.getItem('mytownlens_sponsors') || '{}');
  } catch (e) {}

  delete sponsors[townId];
  localStorage.setItem('mytownlens_sponsors', JSON.stringify(sponsors));

  renderAdminSponsorsData();
  renderHeaderSponsorBadge(currentCity);
  showToast(`Removed sponsor for ${meta.name}`);
}

function resetSponsorForm() {
  const form = document.getElementById('admin-sponsor-form');
  if (form) form.reset();
}

function exportSponsorsCSV() {
  let sponsors = {};
  try {
    sponsors = JSON.parse(localStorage.getItem('mytownlens_sponsors') || '{}');
  } catch (e) {}

  const towns = Object.values(CITY_REGISTRY).sort((a, b) => a.name.localeCompare(b.name));
  const rows = [];

  const escapeCSV = (val) => {
    if (val === null || val === undefined) return '""';
    const s = String(val).replace(/"/g, '""');
    return `"${s}"`;
  };

  rows.push(['Municipality', 'County', 'Status', 'Sponsoring Firm', 'Role', 'Contact Phone', 'Website URL', 'Monthly Recurring Rate', 'Assigned At'].map(escapeCSV).join(','));

  towns.forEach(t => {
    const sp = sponsors[t.id];
    rows.push([
      t.name,
      t.countyShort || t.county,
      sp ? 'Active' : 'Available',
      sp?.name || '',
      sp?.role || '',
      sp?.phone || '',
      sp?.url || '',
      sp?.rate || '',
      sp?.assignedAt || ''
    ].map(escapeCSV).join(','));
  });

  const csvContent = 'data:text/csv;charset=utf-8,' + encodeURIComponent(rows.join('\n'));
  const link = document.createElement('a');
  link.setAttribute('href', csvContent);
  link.setAttribute('download', `mytownlens_sponsorship_roster_${Date.now()}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  showToast(`✓ Exported 47 municipalities roster to CSV`);
}

